INSERT INTO modules (_id, title, description, code, order_num, created_at) VALUES ('6a2d660e3c26ac04a78d8308', 'Module 5: Spreadsheet (Microsoft Excel)', 'Workbooks and Worksheets', NULL, 5, '2026-06-13T14:15:42.278Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO modules (_id, title, description, code, order_num, created_at) VALUES ('6a8452f685e0de577163a431', 'Module 6: Drawing', 'Drawing', NULL, 6, '2026-08-18T12:41:26.790Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38c49a54edb69d22880', '69a5b3884c3ac66e63aa196e', 'Introduction to Computers', 'https://www.youtube.com/embed/zO-7lJTYUcg', 'We learn what a computer actually is and how it takes in information, thinks about it, and gives us a result. We also learn the difference between the physical machine you can touch (hardware) and the invisible instructions that make it work (software).', NULL, NULL, 1, '2026-03-02T15:58:00.983Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38c49a54edb69d22881', '69a5b3884c3ac66e63aa196e', 'Core Components', 'https://www.youtube.com/embed/kVudR7sxdYY', 'We look inside the computer to understand how it works. We learn about its "brain" (the processor), its short-term memory (RAM), and its long-term storage (the Hard Drive).', NULL, NULL, 2, '2026-03-02T15:58:01.044Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38c49a54edb69d22882', '69a5b3884c3ac66e63aa196e', 'The Operating System (System Software)', 'https://www.youtube.com/embed/kAQJ_xaHAHk', 'We meet the "manager" of the computer (Windows 11). We learn how to turn the computer on, log in safely, and find our way around the main screen and basic menus.', NULL, NULL, 3, '2026-03-02T15:58:01.108Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38c49a54edb69d22883', '69a5b3884c3ac66e63aa196e', 'File Management', 'https://www.youtube.com/embed/2lOtuFzqBJg', 'We learn how to organize our digital life. We practice making folders, naming files so they make sense, and moving things around safely so we never lose our hard work.', NULL, NULL, 4, '2026-03-02T15:58:01.161Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38c49a54edb69d22884', '69a5b3884c3ac66e63aa196e', 'Peripherals and Ports', 'https://www.youtube.com/embed/dTWZN2wbXx0', 'We learn how to safely plug things into the computer, like mice, keyboards, and screens. We also learn how to connect wireless tools (like headphones) and how to safely remove USB drives without breaking them.', NULL, NULL, 5, '2026-03-02T15:58:01.225Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38c49a54edb69d22885', '69a5b3884c3ac66e63aa196e', 'Application Software', 'https://www.youtube.com/embed/dTWZN2wbXx0', 'We discover how to find and safely install the specific programs we need to do our work, like writing tools or web browsers. We also learn how to spot fake download buttons so we don''t accidentally download viruses.', NULL, NULL, 6, '2026-03-02T15:58:01.288Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38d49a54edb69d22886', '69a5b3884c3ac66e63aa196e', 'The Boot Process & Troubleshooting', 'https://www.youtube.com/embed/fVK97_cNsF0', 'We learn what to do when the computer freezes or acts up. We cover simple, safe steps to fix everyday problems without panicking or having to call an expensive expert.', NULL, NULL, 7, '2026-03-02T15:58:01.361Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38d49a54edb69d22887', '69a5b3884c3ac66e63aa196e', 'Software and Application', 'https://www.youtube.com/embed/ksyfodbL9gU', 'We learn the difference between programs installed directly on the computer and programs we use over the internet. We also learn how to stop annoying "junk" software from sneaking onto our computer and slowing it down.', NULL, NULL, 8, '2026-03-02T15:58:01.417Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38d49a54edb69d22888', '69a5b3884c3ac66e63aa196e', 'Computer Care & Safety', 'https://www.youtube.com/embed/E3X0JsuhSeY', 'We focus on keeping the physical machine clean and cool so it lasts a long time. More importantly, we learn how to sit and look at the screen correctly so our backs, necks, and eyes stay healthy.', NULL, NULL, 9, '2026-03-02T15:58:01.474Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69a5b38d49a54edb69d22889', '69a5b3884c3ac66e63aa196e', 'Practical Lab', 'https://www.youtube.com/embed/bu-vlh2gg-I', 'This is a hands-on test where students take the driver''s seat. Students will prove they can use all the skills they learned in the first nine lessons to solve real-world tasks with confidence.', NULL, NULL, 10, '2026-03-02T15:58:01.526Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69acc4dab8f95ca598f9768d', '69a6d7f3258e2632ad6e3719', 'Lesson 1: Understanding Files and Folders', 'https://youtu.be/ICdLb8Ppd9Y?si=bF3Xmz6wZluTk35r', 'In this video, we learn the basics of keeping your computer organized. We will look at the difference between "Files" (the actual documents and pictures you make) and "Folders" (the containers that hold your work). We will also explain what "The Cloud" is in a very simple way, so you can understand how your important work stays safe and backed up on the internet.', '1772988761566-523803146.pdf', NULL, 1, '2026-03-08T00:37:46.552Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69ad76b9aaea755878fe9d85', '69a6d7f3258e2632ad6e3719', 'The Windows File Explorer', 'https://youtu.be/4doy6JiE_QM?si=O9wf_GVfUi6FV309', 'se the left-hand menu to jump around, how to change the way your files look (from big pictures to detailed lists), and how to "pin" your favorite folders so they are always just one click away.', NULL, NULL, 2, '2026-03-08T13:16:41.526Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69aea915aaea755878fecb62', '69a6d7f3258e2632ad6e3719', 'Creating, Naming, and Renaming', 'https://youtu.be/zLoX-1CBAv8?si=uT1VPQXmP4Bw7jCI', 'What is in a name? A lot! In this lesson, we learn the professional way to name our files so they sort themselves perfectly. We will explain why you cannot use certain symbols, why putting the date in the name matters, and the fastest keyboard trick (the F2 key) to rename your work in a flash.', NULL, NULL, 3, '2026-03-09T11:03:49.606Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69b14b4daaea755878fee6c3', '69a6d7f3258e2632ad6e3719', 'Managing Data, Copying Moving, and Deleting', 'https://youtu.be/jajmR4RTppY?si=ukrmsnQObdC0USfn', 'Now that we have files, it is time to move them around. We will clearly explain the difference between "Copying" (making a duplicate) and "Cutting" (moving the original). We will practice dragging files across the screen and show you how the Recycle Bin acts as a safety net if you ever delete something by mistake.', NULL, NULL, 4, '2026-03-11T11:00:29.388Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69b68998456d9fffaa1ff1a3', '69a6d7f3258e2632ad6e3719', 'File Extensions and File Types', 'https://youtu.be/o2yeCkVaiXU', 'Have you ever noticed the little letters at the end of a file name, like .pdf or .jpg? These are called "extensions," and they are the secret codes that tell your computer which app to use. In this video, we will unhide these codes, learn what they mean, and see how to change which program opens your files.', NULL, NULL, 5, '2026-03-15T10:27:36.281Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69b94e6d456d9fffaa201c5c', '69a6d7f3258e2632ad6e3719', 'Cloud Storage Integration', 'https://youtu.be/0xL6ZlYud5M?si=eLrTa3neItwrt6GG', 'Cloud Storage Integration', NULL, NULL, 6, '2026-03-17T12:51:57.904Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO lessons (_id, module_id, title, youtube_url, description, notes_path, quiz, order_num, created_at) VALUES ('69bbe185456d9fffaa202ef6', '69a6d7f3258e2632ad6e3719', 'Search and Find', 'https://youtu.be/8lnmq8enzbQ?si=w-pKChaaEXeZL4UM', 'Search and Find', NULL, NULL, 7, '2026-03-19T11:44:05.383Z') ON CONFLICT (_id) DO NOTHING;
