INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e05a', '69a5b3884c3ac66e63aa196e', 24, 'You want to create a folder inside "Documents." What is the first step?', '{"a":"Restart the computer.","b":"Right-click in the empty space and select \"New > Folder.\"","c":"Press the power button.","d":"Open Google Chrome."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.827Z') ON CONFLICT (_id) DO NOTHING;
