INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e05f', '69a5b3884c3ac66e63aa196e', 29, 'Which of these is an INPUT device?', '{"a":"Monitor","b":"Printer","c":"Mouse","d":"Speakers"}'::jsonb, 'c', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.830Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e060', '69a5b3884c3ac66e63aa196e', 30, 'Which of these is an OUTPUT device?', '{"a":"Microphone","b":"Webcam","c":"Scanner","d":"Headphones"}'::jsonb, 'd', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.831Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e065', '69a5b3884c3ac66e63aa196e', 35, 'Why must you "Eject" a USB drive before pulling it out?', '{"a":"To save electricity.","b":"To prevent data corruption (lost files).","c":"To cool down the drive.","d":"It is not necessary; you can just pull it out."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.837Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e06b', '69a5b3884c3ac66e63aa196e', 41, 'Google Docs is an example of a:', '{"a":"Desktop App (Installed)","b":"Web App (Cloud-based)","c":"System Driver","d":"Hardware component"}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.840Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e06f', '69a5b3884c3ac66e63aa196e', 45, 'Which of the following is a Web Browser?', '{"a":"Google","b":"Bing","c":"Microsoft Edge","d":"Windows"}'::jsonb, 'c', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.843Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e072', '69a5b3884c3ac66e63aa196e', 48, 'If you want to save a website to visit later, you should:', '{"a":"Print it out.","b":"Bookmark it.","c":"Memorize the address.","d":"Take a photo of the screen."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.844Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e074', '69a5b3884c3ac66e63aa196e', 50, 'If you double-click a PDF and it opens in the wrong app, how do you fix it permanently?', '{"a":"Delete the PDF.","b":"Right-click > Open With > Choose another app (Check \"Always use this app\").","c":"Restart the computer.","d":"You cannot fix it."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.846Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e07b', '69a5b3884c3ac66e63aa196e', 57, 'What are the two biggest enemies of computer hardware?', '{"a":"Mouse and Keyboard.","b":"Heat and Dust.","c":"Wi-Fi and Bluetooth.","d":"Software and Updates."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.855Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e07c', '69a5b3884c3ac66e63aa196e', 58, 'What is the correct way to clean a computer screen?', '{"a":"Spray Windex directly on the screen.","b":"Use a dry or slightly damp Microfiber cloth.","c":"Scrub hard with a paper towel.","d":"Use a vacuum cleaner."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.856Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e080', '69a5b3884c3ac66e63aa196e', 62, 'The "20-20-20 Rule" helps prevent:', '{"a":"Back pain.","b":"Digital Eye Strain.","c":"Wrist pain.","d":"Overheating."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.862Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e086', '69a5b3884c3ac66e63aa196e', 68, 'When performing a "Hardware Audit," if you see a blue/yellow cable plugged into the wall, it is likely:', '{"a":"Power.","b":"Ethernet (Internet).","c":"HDMI.","d":"Audio."}'::jsonb, 'b', 'Capstone Practical', 'Lesson 10', '2026-03-04T11:00:44.873Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e088', '69a5b3884c3ac66e63aa196e', 70, 'Restarting your computer solves many problems because:', '{"a":"It gives the computer a rest.","b":"It clears the RAM (Memory) and starts fresh.","c":"It deletes old files.","d":"It charges the battery faster."}'::jsonb, 'b', 'Capstone Practical', 'Lesson 10', '2026-03-04T11:00:44.874Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e08d', '69a5b3884c3ac66e63aa196e', 75, 'Which of the following is considered "Peripherals"?', '{"a":"Windows 11","b":"The CPU inside the case","c":"External devices like Printers and Scanners","d":"The Motherboard"}'::jsonb, 'c', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.899Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e096', '69a5b3884c3ac66e63aa196e', 84, 'The "Motherboard" acts like the computer''s:', '{"a":"Brain","b":"Skeleton and Nervous System","c":"Skin","d":"Muscles"}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.918Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e09f', '69a5b3884c3ac66e63aa196e', 93, '"Nesting" folders means:', '{"a":"Hiding folders so no one can see them.","b":"Creating folders inside other folders to stay organized.","c":"Deleting empty folders.","d":"Renaming folders."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.934Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a6', '69a5b3884c3ac66e63aa196e', 100, 'A "Dongle" or "Adapter" is often needed for modern laptops because:', '{"a":"They are too slow.","b":"They are getting thinner and have fewer built-in ports.","c":"They don''t have screens.","d":"They don''t have batteries."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.939Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0aa', '69a5b3884c3ac66e63aa196e', 104, 'What does the "Audio Jack" (3.5mm) look like?', '{"a":"A large rectangle.","b":"A small round hole.","c":"A flat oval.","d":"A square."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.949Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0af', '69a5b3884c3ac66e63aa196e', 109, 'Why should you be careful with "free" software installers?', '{"a":"They might be too good.","b":"They often contain hidden \"Bloatware\" (junk software).","c":"They take up too much space.","d":"They break the mouse."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.952Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b1', '69a5b3884c3ac66e63aa196e', 111, 'Which app would you use to listen to music files on your computer?', '{"a":"Adobe Reader","b":"Media Player (e.g., Spotify or VLC)","c":"Notepad","d":"Calculator"}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.958Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b8', '69a5b3884c3ac66e63aa196e', 118, 'Tabs in a browser allow you to:', '{"a":"Open multiple websites in a single window.","b":"Make the text larger.","c":"Close the browser.","d":"Change the language."}'::jsonb, 'a', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.966Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c3', '69a5b3884c3ac66e63aa196e', 129, 'Why is it bad to use paper towels on a computer screen?', '{"a":"They are too expensive.","b":"They can scratch the delicate surface of the screen.","c":"They leave too much water.","d":"They create static."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.982Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c5', '69a5b3884c3ac66e63aa196e', 131, 'To support your lower back, you should:', '{"a":"Slouch forward.","b":"Sit all the way back in the chair (Lumbar support).","c":"Sit on the edge of the seat.","d":"Stand up."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.983Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c8', '69a5b3884c3ac66e63aa196e', 134, 'To perform a "Hard Restart" when a computer is completely frozen, you:', '{"a":"Unplug the monitor.","b":"Hold the physical power button for 10 seconds.","c":"Click the mouse repeatedly.","d":"Press the Spacebar."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.986Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0ca', '69a5b3884c3ac66e63aa196e', 136, 'If your sound isn''t working, the first thing to check is:', '{"a":"If the printer is plugged in.","b":"If the volume is muted in the System Tray.","c":"If the monitor is on.","d":"The mouse battery."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.988Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0cb', '69a5b3884c3ac66e63aa196e', 137, 'How do you identify an HDMI port visually?', '{"a":"It is round.","b":"It is rectangular.","c":"It has a \"Smile\" shape (flat bottom, rounded top corners).","d":"It is square."}'::jsonb, 'c', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.988Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0cd', '69a5b3884c3ac66e63aa196e', 139, '"End Task" is used to:', '{"a":"Finish a game.","b":"Force a frozen program to close.","c":"Shut down the computer.","d":"Delete a file."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.993Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d2', '69a5b3884c3ac66e63aa196e', 144, 'Which of these is considered "Raw Data"?', '{"a":"A finished report.","b":"The letters typed on a keyboard before they appear on screen.","c":"A printed photo.","d":"A saved file."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.003Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d3', '69a5b3884c3ac66e63aa196e', 145, 'A Stylus (digital pen) is primarily used as an:', '{"a":"Output device.","b":"Input device.","c":"Audio device.","d":"Storage device."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.005Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d7', '69a5b3884c3ac66e63aa196e', 149, 'Which component creates the heat that requires a fan for cooling?', '{"a":"The Hard Drive.","b":"The CPU (Processor).","c":"The Keyboard.","d":"The USB ports."}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:45.010Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d9', '69a5b3884c3ac66e63aa196e', 151, 'A "Bit" is:', '{"a":"The smallest unit of data (0 or 1).","b":"A large file.","c":"A type of monitor.","d":"A brand of mouse."}'::jsonb, 'a', 'Core Components', 'Lesson 2', '2026-03-04T11:00:45.011Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0da', '69a5b3884c3ac66e63aa196e', 152, 'Why do SSDs run more silently than HDDs?', '{"a":"They have fans.","b":"They are smaller.","c":"They have no moving mechanical parts.","d":"They are made of plastic."}'::jsonb, 'c', 'Core Components', 'Lesson 2', '2026-03-04T11:00:45.012Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0dc', '69a5b3884c3ac66e63aa196e', 154, 'If you have 4GB of RAM and want to edit video, you should probably:', '{"a":"Delete files.","b":"Upgrade to 8GB or 16GB of RAM.","c":"Change your mouse.","d":"Use a smaller monitor."}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:45.013Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0de', '69a5b3884c3ac66e63aa196e', 156, 'Why is it important to install "Windows Updates"?', '{"a":"To make the screen brighter.","b":"To fix security holes and protect against new viruses.","c":"To change the desktop background.","d":"To make the mouse faster."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.015Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e0', '69a5b3884c3ac66e63aa196e', 158, 'The picture on your desktop background is often called:', '{"a":"The Saver.","b":"The Wallpaper.","c":"The Cover.","d":"The Paint."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.018Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e3', '69a5b3884c3ac66e63aa196e', 161, 'What is the "Lock Screen"?', '{"a":"A screen that appears when the computer is broken.","b":"The screen you see before entering your password/PIN.","c":"The screen saver.","d":"A virus warning."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.021Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e7', '69a5b3884c3ac66e63aa196e', 165, 'How can you find the largest file in a folder?', '{"a":"Open every file to check.","b":"Click the \"Size\" column header to sort the list.","c":"Rename the files.","d":"Delete small files."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.028Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f7', '69a5b3884c3ac66e63aa196e', 181, 'If a program is "Not Responding," look for this visual cue:', '{"a":"The screen turns black.","b":"The window fades to white and the cursor turns into a spinning circle.","c":"The computer beeps loudly.","d":"The printer starts printing."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.054Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f8', '69a5b3884c3ac66e63aa196e', 182, 'A "Browser Extension" is:', '{"a":"A cable for the browser.","b":"A small add-on that gives your web browser extra features (like an Ad Blocker).","c":"A new monitor.","d":"A longer power cord."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.057Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0fa', '69a5b3884c3ac66e63aa196e', 184, 'The "Refresh" button (circular arrow) on a browser is used to:', '{"a":"Delete the page.","b":"Reload the current page to see updates.","c":"Close the browser.","d":"Search Google."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.058Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0fb', '69a5b3884c3ac66e63aa196e', 185, '"Incognito Mode" or "Private Browsing" means:', '{"a":"You are invisible to the police.","b":"The browser will not save your History or Cookies on that computer.","c":"You get free internet.","d":"You cannot download files."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.061Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0fd', '69a5b3884c3ac66e63aa196e', 187, 'A website ending in .gov is usually:', '{"a":"A commercial business.","b":"A government organization.","c":"A school.","d":"A charity."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.078Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0ff', '69a5b3884c3ac66e63aa196e', 189, 'If you click the "Home" icon in your browser, it takes you to:', '{"a":"Your actual house.","b":"The webpage you set as your starting page.","c":"The desktop.","d":"The settings menu."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.084Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e100', '69a5b3884c3ac66e63aa196e', 190, '"OneDrive" and "Google Drive" are services that:', '{"a":"Speed up your CPU.","b":"Sync your files to the Cloud so you can access them anywhere.","c":"Clean your keyboard.","d":"Play movies."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.086Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e10b', '69a5b3884c3ac66e63aa196e', 201, 'Your feet should be positioned:', '{"a":"Crossed on the chair.","b":"Flat on the floor or on a footrest.","c":"Dangling in the air.","d":"On the desk."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.092Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e10c', '69a5b3884c3ac66e63aa196e', 202, 'To prevent overheating in a Desktop Tower, you should ensure:', '{"a":"The fans are blocked.","b":"The case is wrapped in a blanket.","c":"There is empty space behind the tower for airflow.","d":"The computer is turned off every hour."}'::jsonb, 'c', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.092Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e10f', '69a5b3884c3ac66e63aa196e', 205, 'If you need to find your exact Windows version (e.g., 22H2), you look in:', '{"a":"Task Manager.","b":"Settings > System > About.","c":"The Recycle Bin.","d":"The Calculator."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.094Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e111', '69a5b3884c3ac66e63aa196e', 207, 'If your laptop battery is draining very fast, you might:', '{"a":"Need to lower the screen brightness.","b":"Need to delete files.","c":"Need a new mouse.","d":"Need to type slower."}'::jsonb, 'a', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.096Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e113', '69a5b3884c3ac66e63aa196e', 209, '"Troubleshooting" basically means:', '{"a":"Breaking the computer.","b":"Logical problem solving to fix an issue.","c":"Buying a new computer.","d":"Calling a friend."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.098Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e055', '69a5b3884c3ac66e63aa196e', 19, 'What does "Snap Layouts" allow you to do?', '{"a":"Take a screenshot.","b":"Arrange windows side-by-side perfectly.","c":"Close all apps at once.","d":"Change the color of the screen."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.824Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e056', '69a5b3884c3ac66e63aa196e', 20, 'Where would you find the volume and Wi-Fi status icons?', '{"a":"The Start Menu","b":"The System Tray (bottom right)","c":"The Recycle Bin","d":"The Title Bar"}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.824Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e05c', '69a5b3884c3ac66e63aa196e', 26, 'You accidentally deleted a file. Where should you look first?', '{"a":"The Start Menu","b":"The Recycle Bin","c":"The Internet","d":"The Printer"}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.828Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e05d', '69a5b3884c3ac66e63aa196e', 27, 'Which keyboard shortcut is used to PASTE a file?', '{"a":"Ctrl + C","b":"Ctrl + V","c":"Ctrl + X","d":"Ctrl + P"}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.829Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e066', '69a5b3884c3ac66e63aa196e', 36, 'Which of the following is Application Software?', '{"a":"The Motherboard","b":"Windows 11","c":"Microsoft Excel","d":"The Hard Drive"}'::jsonb, 'c', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.838Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e06e', '69a5b3884c3ac66e63aa196e', 44, 'The "World Wide Web" refers to:', '{"a":"The cables under the ocean.","b":"The collection of websites and pages (The Shops).","c":"The modem in your house.","d":"An spider web."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.842Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e07a', '69a5b3884c3ac66e63aa196e', 56, 'Web Apps (Cloud) are generally better if:', '{"a":"You have no internet.","b":"You need to access your work from multiple different computers.","c":"You need the most powerful features possible.","d":"You want to own the software disc."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.854Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e07e', '69a5b3884c3ac66e63aa196e', 60, '"Ergonomics" refers to:', '{"a":"Setting up your workspace to prevent injury and strain.","b":"The speed of your processor.","c":"The cost of the computer.","d":"Cleaning software."}'::jsonb, 'a', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.857Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e07f', '69a5b3884c3ac66e63aa196e', 61, 'To prevent "Text Neck," your monitor should be:', '{"a":"Looking up at you from the floor.","b":"At eye level (top of the screen).","c":"Looking down from the ceiling.","d":"To the far left side."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.860Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e085', '69a5b3884c3ac66e63aa196e', 67, 'How do you identify a USB-C port visually?', '{"a":"It is a large rectangle.","b":"It is round like a headphone jack.","c":"It is a small, reversible oval.","d":"It has a \"Smile\" shape."}'::jsonb, 'c', 'Capstone Practical', 'Lesson 10', '2026-03-04T11:00:44.872Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e08a', '69a5b3884c3ac66e63aa196e', 72, 'A "2-in-1" or "Hybrid" computer is unique because:', '{"a":"It has two screens.","b":"It can function as both a laptop and a tablet.","c":"It has two keyboards.","d":"It never needs charging."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.885Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e095', '69a5b3884c3ac66e63aa196e', 83, 'If a computer "lags" or slows down when you have too many tabs open, the bottleneck is usually:', '{"a":"The Monitor","b":"The RAM (Memory)","c":"The Mouse","d":"The Keyboard"}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.915Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e099', '69a5b3884c3ac66e63aa196e', 87, 'If you cannot find an app on your computer, the best place to look is:', '{"a":"The Recycle Bin.","b":"The Start Menu Search Bar.","c":"The Settings menu.","d":"The Print dialog."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.929Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a2', '69a5b3884c3ac66e63aa196e', 96, 'Which action moves a file from Folder A to Folder B, removing it from Folder A?', '{"a":"Copy and Paste","b":"Cut and Paste","c":"Duplicate","d":"Shortcut"}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.936Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a7', '69a5b3884c3ac66e63aa196e', 101, 'Which device allows you to input physical documents into the computer?', '{"a":"Printer","b":"Scanner","c":"Monitor","d":"Projector"}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.947Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a8', '69a5b3884c3ac66e63aa196e', 102, 'If a USB device doesn''t work immediately, you should:', '{"a":"Throw it away.","b":"Wait a few seconds for \"Plug and Play\" to finish setting it up.","c":"Pour water on it.","d":"Open the computer case."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.948Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a9', '69a5b3884c3ac66e63aa196e', 103, 'To connect a Bluetooth mouse, you must first put the mouse into:', '{"a":"Sleep Mode","b":"Pairing Mode","c":"Off Mode","d":"Airplane Mode"}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.948Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0ad', '69a5b3884c3ac66e63aa196e', 107, 'Microsoft Word is primarily used for:', '{"a":"Calculating numbers.","b":"Editing photos.","c":"Word Processing (Writing documents).","d":"Playing music."}'::jsonb, 'c', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.950Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b3', '69a5b3884c3ac66e63aa196e', 113, 'A URL is:', '{"a":"A type of computer virus.","b":"The unique address of a website (e.g., https://www.google.com).","c":"A cable used for internet.","d":"A password."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.961Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b4', '69a5b3884c3ac66e63aa196e', 114, 'Which connection type uses a yellow or blue cable and is very stable?', '{"a":"Wi-Fi","b":"Ethernet","c":"Bluetooth","d":"4G"}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.961Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b6', '69a5b3884c3ac66e63aa196e', 116, 'A "Search Engine" (like Google) is used to:', '{"a":"Find information when you don''t know the website address.","b":"Type documents.","c":"Protect your computer from dust.","d":"Play videos offline."}'::jsonb, 'a', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.962Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b7', '69a5b3884c3ac66e63aa196e', 117, '"Bookmarks" or "Favorites" are used to:', '{"a":"Print pages faster.","b":"Save website addresses so you can return to them easily.","c":"Block advertisements.","d":"Speed up the internet."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.963Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0bc', '69a5b3884c3ac66e63aa196e', 122, 'What is the benefit of "Ninite.com"?', '{"a":"It creates viruses.","b":"It installs apps automatically and removes junk/bloatware.","c":"It makes the internet faster.","d":"It gives you free games."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.978Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0bd', '69a5b3884c3ac66e63aa196e', 123, 'Which file extension indicates a Music/Audio file?', '{"a":".docx","b":".mp3","c":".jpg","d":".xlsx"}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.978Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0bf', '69a5b3884c3ac66e63aa196e', 125, 'When installing software, if you see a checkbox for "Install Search Toolbar," you should:', '{"a":"Check it immediately.","b":"Uncheck (Decline) it to avoid junk software.","c":"Stop the installation.","d":"Turn off the computer."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.979Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c0', '69a5b3884c3ac66e63aa196e', 126, '"Offline Access" is a major advantage of:', '{"a":"Web Apps.","b":"Desktop Apps (Installed).","c":"Cloud Storage.","d":"Streaming Services."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.980Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c6', '69a5b3884c3ac66e63aa196e', 132, 'The "20-20-20 Rule" suggests looking 20 feet away every 20 minutes for:', '{"a":"20 Minutes.","b":"20 Seconds.","c":"20 Hours.","d":"2 Seconds."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.984Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c9', '69a5b3884c3ac66e63aa196e', 135, 'The shortcut Ctrl + Shift + Esc opens:', '{"a":"The Start Menu.","b":"The Task Manager.","c":"The Internet.","d":"The Settings."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.987Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0ce', '69a5b3884c3ac66e63aa196e', 140, 'Why is "Restarting" often better than "Shutting Down" for fixing problems?', '{"a":"It is faster.","b":"It fully clears the memory (RAM) and resets the software state.","c":"It saves power.","d":"It updates the hardware."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.995Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d0', '69a5b3884c3ac66e63aa196e', 142, 'A "Smart Watch" is an example of:', '{"a":"Analog technology.","b":"A wearable computer.","c":"Mechanical hardware.","d":"System software."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.002Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d5', '69a5b3884c3ac66e63aa196e', 147, 'Which of the following would be considered "External Hardware"?', '{"a":"The Motherboard.","b":"The CPU fan.","c":"A Projector connected via HDMI.","d":"The RAM sticks."}'::jsonb, 'c', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.009Z') ON CONFLICT (_id) DO NOTHING;
