INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0dd', '69a5b3884c3ac66e63aa196e', 155, '"Linux" is an example of:', '{"a":"An Open-Source Operating System.","b":"A Web Browser.","c":"A type of Hardware.","d":"A Virus."}'::jsonb, 'a', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.013Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0df', '69a5b3884c3ac66e63aa196e', 157, 'Which shortcut allows you to lock your screen immediately when walking away?', '{"a":"Ctrl + L","b":"Windows Key + L","c":"Alt + L","d":"Shift + L"}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.017Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e2', '69a5b3884c3ac66e63aa196e', 160, 'A "Guest Account" on a computer typically:', '{"a":"Has full Administrator power.","b":"Cannot install software or change system settings.","c":"Can delete anyone''s files.","d":"Is used for hacking."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.020Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e6', '69a5b3884c3ac66e63aa196e', 164, 'What is a "ZIP" file?', '{"a":"A corrupt file.","b":"A compressed folder that makes files smaller for emailing.","c":"A video file.","d":"A virus."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.026Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0ea', '69a5b3884c3ac66e63aa196e', 168, '"Date Modified" tells you:', '{"a":"When the file was created.","b":"The last time the file was changed or saved.","c":"When the file will be deleted.","d":"Who owns the file."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.034Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0ed', '69a5b3884c3ac66e63aa196e', 171, 'Which device allows you to hear audio without disturbing others?', '{"a":"Speakers.","b":"Headset/Headphones.","c":"Microphone.","d":"Sound Bar."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.035Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f0', '69a5b3884c3ac66e63aa196e', 174, 'If your mouse is "jumping" around the screen, you should check:', '{"a":"The internet connection.","b":"If the surface/mousepad is clean and flat.","c":"The printer ink.","d":"The volume."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.040Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f2', '69a5b3884c3ac66e63aa196e', 176, 'What is the difference between "Save" and "Save As"?', '{"a":"No difference.","b":"\"Save\" updates the current file; \"Save As\" creates a new copy with a different name.","c":"\"Save\" deletes the file; \"Save As\" keeps it.","d":"\"Save As\" is faster."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.041Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f3', '69a5b3884c3ac66e63aa196e', 177, 'Which app is best suited for creating a slideshow presentation?', '{"a":"Microsoft Excel","b":"Microsoft PowerPoint","c":"Notepad","d":"Calculator"}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.042Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f4', '69a5b3884c3ac66e63aa196e', 178, 'Adobe Acrobat Reader is commonly used to view:', '{"a":"Videos (.mp4)","b":"Music (.mp3)","c":"PDF Documents (.pdf)","d":"Webpages (.html)"}'::jsonb, 'c', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.042Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f5', '69a5b3884c3ac66e63aa196e', 179, 'Zoom and Microsoft Teams are examples of:', '{"a":"Word Processors.","b":"Video Conferencing / Communication software.","c":"Antivirus software.","d":"Games."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.051Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0fc', '69a5b3884c3ac66e63aa196e', 186, 'What does the "History" menu in a browser show?', '{"a":"The history of the world.","b":"A list of websites you visited in the past days/weeks.","c":"Your saved passwords.","d":"Your emails."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.076Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e101', '69a5b3884c3ac66e63aa196e', 191, 'Pinning an app to the "Start Menu" means:', '{"a":"It will run every time you turn on the computer.","b":"It creates a tile in the Start Menu for easy access.","c":"It cannot be deleted.","d":"It is hidden."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.087Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e109', '69a5b3884c3ac66e63aa196e', 199, 'Why should you keep magnets away from older mechanical Hard Drives?', '{"a":"Magnets can erase data on magnetic platters.","b":"Magnets make the drive faster.","c":"Magnets melt the plastic.","d":"Magnets block the Wi-Fi."}'::jsonb, 'a', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.091Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e10d', '69a5b3884c3ac66e63aa196e', 203, 'Repetitive Strain Injury (RSI) is caused by:', '{"a":"A virus.","b":"Doing the same small movements (like clicking) over and over without breaks.","c":"Watching too many videos.","d":"Dust in the keyboard."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.093Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e10e', '69a5b3884c3ac66e63aa196e', 204, 'The Windows Key + E shortcut opens:', '{"a":"Edge Browser.","b":"File Explorer.","c":"Email.","d":"Everything."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.093Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e112', '69a5b3884c3ac66e63aa196e', 208, 'The "Mute" button usually looks like:', '{"a":"A speaker with a cross (X) or line through it.","b":"A trash can.","c":"A magnifying glass.","d":"A padlock."}'::jsonb, 'a', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.098Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e045', '69a5b3884c3ac66e63aa196e', 3, 'Which of these is an example of HARDWARE?', '{"a":"Microsoft Word","b":"The Monitor (Screen)","c":"Windows 11","d":"A Video Game"}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.807Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e049', '69a5b3884c3ac66e63aa196e', 7, 'What happens during the "Boot Process"?', '{"a":"The computer cleans its screen.","b":"The computer checks its hardware and loads the Operating System.","c":"The computer connects to the internet instantly.","d":"The computer deletes old files."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.812Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e04b', '69a5b3884c3ac66e63aa196e', 9, 'RAM stands for:', '{"a":"Read Access Memory","b":"Random Access Memory","c":"Real Active Memory","d":"Rapid Action Mode"}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.815Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e04c', '69a5b3884c3ac66e63aa196e', 10, 'What happens to data in RAM when the power is turned off?', '{"a":"It is saved permanently.","b":"It is uploaded to the cloud.","c":"It is completely erased (Volatile).","d":"It moves to the Hard Drive automatically."}'::jsonb, 'c', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.818Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e04f', '69a5b3884c3ac66e63aa196e', 13, 'Which unit of measurement is the LARGEST?', '{"a":"Gigabyte (GB)","b":"Megabyte (MB)","c":"Terabyte (TB)","d":"Kilobyte (KB)"}'::jsonb, 'c', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.820Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e051', '69a5b3884c3ac66e63aa196e', 15, 'What is the main role of an Operating System (OS)?', '{"a":"To manage hardware and software resources.","b":"To browse the internet only.","c":"To create spreadsheets.","d":"To clean viruses."}'::jsonb, 'a', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.821Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e054', '69a5b3884c3ac66e63aa196e', 18, 'To hide a window without closing it, you click:', '{"a":"Minimize (The Dash)","b":"Maximize (The Square)","c":"Close (The X)","d":"Delete"}'::jsonb, 'a', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.823Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e058', '69a5b3884c3ac66e63aa196e', 22, 'What tool do we use to manage files and folders in Windows?', '{"a":"Internet Explorer","b":"File Explorer (Yellow Folder)","c":"Task Manager","d":"Settings"}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.826Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e05e', '69a5b3884c3ac66e63aa196e', 28, 'Scenario: You have a photo named "Image1.jpg". You want to change it to "Holiday.jpg". You should:', '{"a":"Delete the file and take a new photo.","b":"Right-click and select \"Rename.\"","c":"Email it to yourself.","d":"Open it in Paint."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.829Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e061', '69a5b3884c3ac66e63aa196e', 31, 'Which port is known for being "reversible" (can plug in upside down)?', '{"a":"USB-A","b":"HDMI","c":"USB-C","d":"VGA"}'::jsonb, 'c', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.834Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e068', '69a5b3884c3ac66e63aa196e', 38, 'What is the safest place to download apps on Windows 11?', '{"a":"Any website that says \"Free Download.\"","b":"The Microsoft Store.","c":"A link in a spam email.","d":"A pop-up advertisement."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.839Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e069', '69a5b3884c3ac66e63aa196e', 39, 'What is "Bloatware"?', '{"a":"Software that makes your computer faster.","b":"Unwanted \"junk\" software that comes pre-installed or bundled with other apps.","c":"Software for designing boats.","d":"Essential system updates."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.839Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e06a', '69a5b3884c3ac66e63aa196e', 40, 'How should you remove a program you no longer need?', '{"a":"Delete the icon on the Desktop.","b":"Go to Settings > Apps > Uninstall.","c":"Rename the folder to \"Hidden.\"","d":"Turn off the monitor."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.840Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e06c', '69a5b3884c3ac66e63aa196e', 42, 'Why should you update your apps?', '{"a":"To fill up the hard drive.","b":"To fix security holes and get new features.","c":"To change the color of the icon.","d":"Updates are never necessary."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.841Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e06d', '69a5b3884c3ac66e63aa196e', 43, 'The "Internet" refers to:', '{"a":"The websites you visit.","b":"The physical network of cables and computers (The Road).","c":"Google Chrome only.","d":"Your Wi-Fi password."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.842Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e070', '69a5b3884c3ac66e63aa196e', 46, 'Where do you type a specific website address (URL)?', '{"a":"The Search Bar in the middle of the page.","b":"The Address Bar at the very top.","c":"The Start Menu.","d":"A Word document."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.843Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e075', '69a5b3884c3ac66e63aa196e', 51, 'When installing free software, you should:', '{"a":"Click \"Next\" as fast as possible.","b":"Read carefully and uncheck boxes for extra \"junk\" software.","c":"Provide your credit card details immediately.","d":"Turn off your antivirus."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.846Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e081', '69a5b3884c3ac66e63aa196e', 63, 'If you spill water on your laptop, the first thing you must do is:', '{"a":"Turn it off and unplug it immediately.","b":"Use a hair dryer on hot.","c":"Shake it violently.","d":"Turn it on to see if it works."}'::jsonb, 'a', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.863Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e082', '69a5b3884c3ac66e63aa196e', 64, 'To check your computer''s RAM and CPU specs, you go to:', '{"a":"File Explorer > Downloads.","b":"Settings > System > About.","c":"The Recycle Bin.","d":"Microsoft Edge."}'::jsonb, 'b', 'Capstone Practical', 'Lesson 10', '2026-03-04T11:00:44.868Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e084', '69a5b3884c3ac66e63aa196e', 66, 'In Task Manager, to stop a frozen app, you click:', '{"a":"Delete App.","b":"End Task.","c":"Restart Windows.","d":"New Task."}'::jsonb, 'b', 'Capstone Practical', 'Lesson 10', '2026-03-04T11:00:44.872Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e087', '69a5b3884c3ac66e63aa196e', 69, 'You want to arrange three windows on one screen. You should use:', '{"a":"Snap Layouts (Hover over Maximize).","b":"Minimize all windows.","c":"Close two windows.","d":"Buy two more monitors."}'::jsonb, 'a', 'Capstone Practical', 'Lesson 10', '2026-03-04T11:00:44.874Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e08b', '69a5b3884c3ac66e63aa196e', 73, 'Which of these is NOT a stage in the IPOS cycle?', '{"a":"Input","b":"Output","c":"Charging","d":"Processing"}'::jsonb, 'c', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.886Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e08c', '69a5b3884c3ac66e63aa196e', 74, 'When you tap on a touchscreen to open an app, the screen is acting as:', '{"a":"An Output device only.","b":"An Input device only.","c":"Both an Input and Output device.","d":"A Storage device."}'::jsonb, 'c', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.893Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e08e', '69a5b3884c3ac66e63aa196e', 76, '"Digital Literacy" in 2026 primarily means:', '{"a":"Knowing how to fix broken hardware.","b":"Having the skills to use technology safely and effectively in daily life.","c":"Knowing how to write computer code.","d":"Having the most expensive computer."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.899Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e090', '69a5b3884c3ac66e63aa196e', 78, 'Which component is responsible for "thinking" and calculations?', '{"a":"The Hard Drive","b":"The RAM","c":"The CPU (Processor)","d":"The Fan"}'::jsonb, 'c', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.901Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e091', '69a5b3884c3ac66e63aa196e', 79, 'Clock speed (measured in GHz) determines:', '{"a":"How much data you can store.","b":"How fast the CPU can process instructions.","c":"How loud the speakers are.","d":"How fast the internet connects."}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.901Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e092', '69a5b3884c3ac66e63aa196e', 80, 'Why is a "Quad-Core" processor generally better than a "Dual-Core"?', '{"a":"It uses less electricity.","b":"It can handle more tasks at the same time (multitasking).","c":"It is physically smaller.","d":"It is cheaper."}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:44.907Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e098', '69a5b3884c3ac66e63aa196e', 86, 'The "System Tray" (near the clock) allows you to:', '{"a":"Open new programs.","b":"Check system health like battery and Wi-Fi.","c":"Type documents.","d":"Delete files."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.928Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e09a', '69a5b3884c3ac66e63aa196e', 88, 'What happens when you click the "Restore Down" button on a window?', '{"a":"It closes the window.","b":"It makes the window fill the whole screen.","c":"It returns the window to a smaller, movable size.","d":"It deletes the window."}'::jsonb, 'c', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.931Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e09c', '69a5b3884c3ac66e63aa196e', 90, 'Which shortcut allows you to switch between open apps quickly?', '{"a":"Alt + Tab","b":"Ctrl + S","c":"Windows Key + D","d":"Shift + Enter"}'::jsonb, 'a', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.933Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a1', '69a5b3884c3ac66e63aa196e', 95, 'If you rename Report.pdf to just Report, what might happen?', '{"a":"The file becomes smaller.","b":"The computer might not know which app to use to open it.","c":"The file is deleted.","d":"Nothing happens."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.935Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0a3', '69a5b3884c3ac66e63aa196e', 97, 'What is the keyboard shortcut for "Undo" (fixing a mistake)?', '{"a":"Ctrl + Z","b":"Ctrl + C","c":"Ctrl + U","d":"Ctrl + X"}'::jsonb, 'a', 'File Management', 'Lesson 4', '2026-03-04T11:00:44.937Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0ac', '69a5b3884c3ac66e63aa196e', 106, 'Which of these is NOT an example of a Web Browser?', '{"a":"Mozilla Firefox","b":"Microsoft Edge","c":"VLC Media Player","d":"Google Chrome"}'::jsonb, 'c', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.950Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b0', '69a5b3884c3ac66e63aa196e', 110, 'To verify a safe download, you should check:', '{"a":"The color of the button.","b":"The URL (Address) to make sure it is the official site.","c":"If the button is flashing.","d":"If the site asks for money."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.952Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b2', '69a5b3884c3ac66e63aa196e', 112, 'If you delete a shortcut icon from the desktop, does it uninstall the program?', '{"a":"Yes, completely.","b":"No, it only deletes the shortcut, not the app.","c":"Yes, but only if you restart.","d":"No, it deletes the internet."}'::jsonb, 'b', 'Application Software', 'Lesson 6', '2026-03-04T11:00:44.960Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b5', '69a5b3884c3ac66e63aa196e', 115, 'When text is blue and underlined on a webpage, it is usually:', '{"a":"A mistake.","b":"A Hyperlink.","c":"A virus.","d":"Important warning text."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.962Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c4', '69a5b3884c3ac66e63aa196e', 130, 'The top of your monitor should be level with:', '{"a":"Your chin.","b":"Your eyes / eyebrows.","c":"The desk surface.","d":"The ceiling."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.983Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c7', '69a5b3884c3ac66e63aa196e', 133, '"Night Light" or "Blue Light Filter" helps to:', '{"a":"Save battery.","b":"Reduce eye strain and sleep disruption in the evening.","c":"Make the screen brighter.","d":"Clean the screen."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.985Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d1', '69a5b3884c3ac66e63aa196e', 143, 'Data enters the computer during the _____ stage.', '{"a":"Output","b":"Storage","c":"Input","d":"Processing"}'::jsonb, 'c', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.003Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d4', '69a5b3884c3ac66e63aa196e', 146, 'Computers have "Form Factors." What does this mean?', '{"a":"The speed of the computer.","b":"The physical shape and size of the computer.","c":"The cost of the computer.","d":"The brand of the computer."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.005Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d6', '69a5b3884c3ac66e63aa196e', 148, 'At the most basic level, computers understand data as "Binary Code," which consists of:', '{"a":"Letters A-Z.","b":"Numbers 1-10.","c":"Zeros (0) and Ones (1).","d":"English words."}'::jsonb, 'c', 'Core Components', 'Lesson 2', '2026-03-04T11:00:45.010Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e1', '69a5b3884c3ac66e63aa196e', 159, 'If you want an app to stay on your Taskbar even when it is closed, you should:', '{"a":"Delete it.","b":"Right-click and select \"Pin to taskbar.\"","c":"Open it twice.","d":"Save it as a file."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:45.019Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e4', '69a5b3884c3ac66e63aa196e', 162, 'To select multiple files that are NOT next to each other, you hold down which key while clicking?', '{"a":"Shift","b":"Ctrl (Control)","c":"Alt","d":"Spacebar"}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.022Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e9', '69a5b3884c3ac66e63aa196e', 167, 'If you drag a file from your C: Drive to a USB Drive, Windows usually defaults to:', '{"a":"Moving (Cutting) it.","b":"Copying it.","c":"Deleting it.","d":"Renaming it."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.033Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0eb', '69a5b3884c3ac66e63aa196e', 169, 'What does an Ethernet (Network) cable usually look like?', '{"a":"A flat black ribbon.","b":"A thick cable with a plug that looks like a large telephone jack (RJ45).","c":"A round plug.","d":"A small oval."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.034Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0ef', '69a5b3884c3ac66e63aa196e', 173, '"Airplane Mode" on a laptop:', '{"a":"Makes the laptop fly.","b":"Turns off all wireless signals (Wi-Fi and Bluetooth).","c":"Turns up the fan speed.","d":"Dims the screen."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.038Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f1', '69a5b3884c3ac66e63aa196e', 175, 'Which port is circular and often colored Green (for Audio) or Pink (for Mic) on older PCs?', '{"a":"USB","b":"3.5mm Audio Jacks","c":"HDMI","d":"Ethernet"}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.041Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f9', '69a5b3884c3ac66e63aa196e', 183, 'What is an ISP?', '{"a":"Internet Service Provider (the company you pay for internet).","b":"Internet Speed Program.","c":"Internal System Processor.","d":"International Server Protocol."}'::jsonb, 'a', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.058Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0fe', '69a5b3884c3ac66e63aa196e', 188, 'A "Modem" or "Router" is the device that:', '{"a":"Prints your emails.","b":"Connects your home network to the Internet Service Provider.","c":"Cleans viruses.","d":"Plays music."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:45.081Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e102', '69a5b3884c3ac66e63aa196e', 192, 'What does a "Shield" icon on an installer button usually mean?', '{"a":"The file is a virus.","b":"The action requires Administrator permission.","c":"The file is safe.","d":"The file is broken."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.087Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e104', '69a5b3884c3ac66e63aa196e', 194, 'If a website asks to "Send you Notifications," you should generally:', '{"a":"Click Allow immediately.","b":"Click Block (unless you really want them), as they can be annoying.","c":"Turn off the computer.","d":"Unplug the mouse."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.088Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e106', '69a5b3884c3ac66e63aa196e', 196, 'If you see a file named Setup.exe, it is likely:', '{"a":"A picture.","b":"An installer for a program.","c":"A document.","d":"A virus."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.090Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e107', '69a5b3884c3ac66e63aa196e', 197, 'A "Surge Protector" helps protect your computer from:', '{"a":"Dust.","b":"Water spills.","c":"Spikes in electricity (lightning strikes).","d":"Hackers."}'::jsonb, 'c', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.090Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e043', '69a5b3884c3ac66e63aa196e', 1, 'Which of the following best defines a "computer"?', '{"a":"A machine that only plays games.","b":"An electronic device that manipulates information or data.","c":"A screen that shows movies.","d":"A typewriter with a screen."}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:44.803Z') ON CONFLICT (_id) DO NOTHING;
