INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e09b', '69a5b3884c3ac66e63aa196e', 89, '"Snap Layouts" are most useful for:', '{"a":"Playing videos.","b":"Multitasking with two or more windows visible at once.","c":"Cleaning the desktop.","d":"Shutting down faster."}'::jsonb, 'b', 'The Operating System', 'Lesson 3', '2026-03-04T11:00:44.932Z') ON CONFLICT (_id) DO NOTHING;
