INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0ab', '69a5b3884c3ac66e63aa196e', 105, 'Pulling out a USB drive while data is writing can cause:', '{"a":"A fire.","b":"Data Corruption (Broken files).","c":"The internet to disconnect.","d":"The monitor to turn off."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:44.949Z') ON CONFLICT (_id) DO NOTHING;
