INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0b9', '69a5b3884c3ac66e63aa196e', 119, '"The Cloud" effectively means:', '{"a":"Satellites in the sky.","b":"Servers (computers) connected to the internet where you store data.","c":"Wireless electricity.","d":"Rain."}'::jsonb, 'b', 'The Internet and Web', 'Lesson 7', '2026-03-04T11:00:44.967Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0ba', '69a5b3884c3ac66e63aa196e', 120, 'What is a "Default App"?', '{"a":"An app that is broken.","b":"The app Windows automatically uses to open a specific file type.","c":"An app you cannot delete.","d":"An app that costs money."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.972Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0bb', '69a5b3884c3ac66e63aa196e', 121, 'If you want all .jpg files to open in a different viewer, you should change:', '{"a":"The file name.","b":"The \"Default Apps\" settings.","c":"The monitor resolution.","d":"The mouse settings."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.976Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0be', '69a5b3884c3ac66e63aa196e', 124, 'Why might you choose a Web App (like Google Docs) over a Desktop App?', '{"a":"You have no internet connection.","b":"You want to access your documents from any computer in the world.","c":"You want manual updates.","d":"It uses more hard drive space."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:44.979Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c1', '69a5b3884c3ac66e63aa196e', 127, 'Static electricity can:', '{"a":"Charge your battery.","b":"Damage delicate internal computer parts.","c":"Clean the screen.","d":"Speed up the CPU."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.981Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0c2', '69a5b3884c3ac66e63aa196e', 128, 'Thermal Throttling happens when:', '{"a":"The computer is too cold.","b":"The computer gets too hot and slows down to protect itself.","c":"The internet is slow.","d":"You run out of storage."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:44.982Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810dcc073a3d3d397e0cc', '69a5b3884c3ac66e63aa196e', 138, 'Checking "System > About" is useful for:', '{"a":"Finding out how much RAM and what CPU you have.","b":"Changing your wallpaper.","c":"Browsing the web.","d":"Playing games."}'::jsonb, 'a', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:44.992Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0cf', '69a5b3884c3ac66e63aa196e', 141, 'Which type of computer is designed to "serve" information to other computers on a network (like the Internet)?', '{"a":"Laptop","b":"Server","c":"Tablet","d":"Calculator"}'::jsonb, 'b', 'Introduction to Computers', 'Lesson 1', '2026-03-04T11:00:45.002Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0d8', '69a5b3884c3ac66e63aa196e', 150, 'The "Power Supply Unit" (PSU) does what?', '{"a":"Stores data when power is off.","b":"Converts electricity from the wall outlet to power the internal components.","c":"Connects to the internet.","d":"Prints documents."}'::jsonb, 'b', 'Core Components', 'Lesson 2', '2026-03-04T11:00:45.011Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e5', '69a5b3884c3ac66e63aa196e', 163, 'To select a list of files from the top to the bottom (a range), you hold down:', '{"a":"Shift","b":"Ctrl","c":"Enter","d":"Tab"}'::jsonb, 'a', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.022Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0e8', '69a5b3884c3ac66e63aa196e', 166, 'What is the "Quick Access" menu in File Explorer?', '{"a":"A way to delete files fast.","b":"A list of your most frequently used folders pinned to the top left.","c":"A fast internet connection.","d":"A shutdown button."}'::jsonb, 'b', 'File Management', 'Lesson 4', '2026-03-04T11:00:45.033Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0ec', '69a5b3884c3ac66e63aa196e', 170, 'Why might you cover your Webcam when not in use?', '{"a":"To keep it warm.","b":"To stop dust.","c":"For privacy and security against hackers.","d":"To save battery."}'::jsonb, 'c', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.035Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0ee', '69a5b3884c3ac66e63aa196e', 172, 'A "USB Hub" allows you to:', '{"a":"Make the internet faster.","b":"Turn one USB port into multiple USB ports.","c":"Cool down the computer.","d":"Charge the battery wirelessly."}'::jsonb, 'b', 'Peripherals and Ports', 'Lesson 5', '2026-03-04T11:00:45.036Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e0f6', '69a5b3884c3ac66e63aa196e', 180, '"Open Source" software (like VLC Player or Linux) usually means:', '{"a":"It is free to use and the code is public.","b":"It is very expensive.","c":"It is full of viruses.","d":"It only works on Mondays."}'::jsonb, 'a', 'Application Software', 'Lesson 6', '2026-03-04T11:00:45.053Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e103', '69a5b3884c3ac66e63aa196e', 193, 'Why might you create a "Shortcut" on your Desktop?', '{"a":"To make the file smaller.","b":"To access a file buried deep in folders without moving the original.","c":"To delete the original file.","d":"To rename the file."}'::jsonb, 'b', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.088Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e105', '69a5b3884c3ac66e63aa196e', 195, '"Proprietary Software" usually requires:', '{"a":"You to pay for a license (e.g., buying Microsoft Office).","b":"You to fix the code yourself.","c":"No installation.","d":"An internet connection only."}'::jsonb, 'a', 'Software Safety & Defaults', 'Lesson 8', '2026-03-04T11:00:45.089Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e108', '69a5b3884c3ac66e63aa196e', 198, 'When using "Compressed Air" to clean a keyboard, you should:', '{"a":"Shake the can violently while spraying.","b":"Hold the can upright and use short bursts.","c":"Turn the can upside down.","d":"Spray it on the screen."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.091Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e10a', '69a5b3884c3ac66e63aa196e', 200, '"Blinking" more often while using a computer helps reduce:', '{"a":"Back pain.","b":"Dry eyes.","c":"Wrist strain.","d":"Neck pain."}'::jsonb, 'b', 'Care and Safety', 'Lesson 9', '2026-03-04T11:00:45.091Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e110', '69a5b3884c3ac66e63aa196e', 206, 'A "Hard Reboot" (holding the power button) should be used:', '{"a":"Every day.","b":"Only when the computer is completely frozen and won''t restart normally.","c":"To save power.","d":"To delete files."}'::jsonb, 'b', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.095Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69a810ddc073a3d3d397e114', '69a5b3884c3ac66e63aa196e', 210, 'If you cannot hear any sound, but the volume is up, you should check:', '{"a":"If the speakers/headphones are actually plugged into the correct port.","b":"If the printer has paper.","c":"If the mouse is working.","d":"If the Wi-Fi is on."}'::jsonb, 'a', 'Capstone Practical & Troubleshooting', 'Lesson 10', '2026-03-04T11:00:45.099Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275971ff', '69a6d7f3258e2632ad6e3719', 5, 'What is the universal shortcut to instantly "Undo" an accidental mistake, like dropping a folder in the wrong place?', '{"a":"Ctrl + C","b":"Ctrl + X","c":"Ctrl + Z","d":"Ctrl + V"}'::jsonb, 'c', 'Undo Command', 'Lesson 1', '2026-03-22T12:17:57.144Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597209', '69a6d7f3258e2632ad6e3719', 15, 'Why should you never use characters like < > : " / \ | ? * when naming a file?', '{"a":"They make the file size too big.","b":"They are considered unprofessional.","c":"They are deeply reserved for the system''s core code and will corrupt the file.","d":"They are only allowed on Apple Mac computers."}'::jsonb, 'c', 'Illegal Characters', 'Lesson 3', '2026-03-22T12:17:57.149Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759720a', '69a6d7f3258e2632ad6e3719', 16, 'What is the internationally standardized, professional way to write a date in a file name?', '{"a":"Day-Month-Year (DD-MM-YYYY)","b":"Month-Day-Year (MM-DD-YYYY)","c":"Year-Month-Day (YYYY-MM-DD)","d":"Year-Day-Month (YYYY-DD-MM)"}'::jsonb, 'c', 'ISO Date Format', 'Lesson 3', '2026-03-22T12:17:57.150Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759720c', '69a6d7f3258e2632ad6e3719', 18, 'What is the professional way to handle "Version Control" instead of naming files "Draft" or "Copy of Copy"?', '{"a":"Use a different language for each file.","b":"Use sequential numbering, like v01, v02, v03.","c":"Do not name the file at all.","d":"Put the word \"FINAL\" at the end of every file."}'::jsonb, 'b', 'Version Control', 'Lesson 3', '2026-03-22T12:17:57.151Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759720e', '69a6d7f3258e2632ad6e3719', 20, 'What is the first thing you should do when starting a brand new project on your computer?', '{"a":"Start typing your document immediately.","b":"Build the folder (\"the fridge\") first so you have a place to save your work safely.","c":"Connect a USB drive.","d":"Open your email."}'::jsonb, 'b', 'Project Startup', 'Lesson 3', '2026-03-22T12:17:57.152Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597210', '69a6d7f3258e2632ad6e3719', 22, 'What happens to the original file when you use the "Copy" command?', '{"a":"The original file is deleted.","b":"The original file remains in its exact place, and a duplicate is created elsewhere.","c":"The original file is sent to the Recycle Bin.","d":"The original file is renamed."}'::jsonb, 'b', 'Copying Data', 'Lesson 4', '2026-03-22T12:17:57.153Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597212', '69a6d7f3258e2632ad6e3719', 24, 'What invisible, temporary holding area does the computer use when you copy or cut a file?', '{"a":"The Hard Drive","b":"The Cloud","c":"The Clipboard","d":"The Recycle Bin"}'::jsonb, 'c', 'The Clipboard', 'Lesson 4', '2026-03-22T12:17:57.154Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597217', '69a6d7f3258e2632ad6e3719', 29, 'What is a file extension?', '{"a":"The first name of a file.","b":"The folder where a file is kept.","c":"A tiny dot and a few letters at the end of a file name that tell the system what type of file it is.","d":"The size of the file in megabytes."}'::jsonb, 'c', 'File Extension', 'Lesson 5', '2026-03-22T12:17:57.156Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597223', '69a6d7f3258e2632ad6e3719', 41, 'Why has sharing a Cloud link largely replaced handing someone a USB drive?', '{"a":"Because USB drives are too heavy to carry.","b":"Because it is safer, instant, and you do not have to give away your physical hardware.","c":"Because you can only put one file on a USB drive.","d":"Because the Cloud is completely free forever."}'::jsonb, 'b', 'Cloud Links', 'Lesson 6', '2026-03-22T12:17:57.160Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597224', '69a6d7f3258e2632ad6e3719', 42, 'Which icon indicates that a OneDrive file is only available when you have an active internet connection?', '{"a":"A green circle with a checkmark","b":"A solid green circle","c":"A blue cloud icon","d":"A red X"}'::jsonb, 'c', 'Online-Only Icons', 'Lesson 6', '2026-03-22T12:17:57.160Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597226', '69a6d7f3258e2632ad6e3719', 44, 'What are specific commands like type: or ext: known as in computer science?', '{"a":"Advanced Query Syntax (AQS)","b":"Basic Typing Rules","c":"Cloud Commands","d":"System Errors"}'::jsonb, 'a', 'AQS Commands', 'Lesson 7', '2026-03-22T12:17:57.161Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597228', '69a6d7f3258e2632ad6e3719', 46, 'What does the "Date Modified" filter help you do?', '{"a":"It changes the time on your computer clock.","b":"It lets you find a file based on exactly when you last changed it, effectively acting like time travel for your files.","c":"It deletes files that are too old.","d":"It schedules an email to be sent later."}'::jsonb, 'b', 'Date Filters', 'Lesson 7', '2026-03-22T12:17:57.161Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759722a', '69a6d7f3258e2632ad6e3719', 48, 'Why is it important to choose the right folder before you start typing in the search bar?', '{"a":"Because searching \"This PC\" searches the entire computer and takes much longer than searching a specific folder.","b":"Because the search bar will break if you are in the wrong folder.","c":"Because you can only search one folder per day.","d":"Because the computer will delete files if you search too broadly."}'::jsonb, 'a', 'Scoped Search', 'Lesson 7', '2026-03-22T12:17:57.161Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759722e', '69a6d7f3258e2632ad6e3719', 52, 'What is the digital equivalent of a "vacuum seal bag" that shrinks the physical size of your data?', '{"a":"A copied file","b":"A Word document","c":"A ZIP archive","d":"A Cloud folder"}'::jsonb, 'c', 'ZIP Archives', 'Lesson 8', '2026-03-22T12:17:57.163Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759722f', '69a6d7f3258e2632ad6e3719', 53, 'How does Lossless Data Compression work in a ZIP file?', '{"a":"It deletes random words to make the file smaller.","b":"It lowers the visual quality and resolution of your photos permanently.","c":"It replaces large, repeating binary patterns with tiny mathematical shortcuts to save space without destroying any data.","d":"It cuts the file in half and sends it in two emails."}'::jsonb, 'c', 'Lossless Compression', 'Lesson 8', '2026-03-22T12:17:57.163Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597230', '69a6d7f3258e2632ad6e3719', 54, 'What happens when you use the "Extract" command on a ZIP file?', '{"a":"The file is sent to the Recycle Bin.","b":"The computer reads the mathematical shortcuts and puts the exact data back perfectly, byte-for-byte.","c":"The files are uploaded to the Cloud.","d":"The ZIP file is renamed."}'::jsonb, 'b', 'Extraction', 'Lesson 8', '2026-03-22T12:17:57.163Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597233', '69a6d7f3258e2632ad6e3719', 57, 'When is a physical removable drive, like a USB flash drive, absolutely necessary?', '{"a":"When you have a very fast fiber internet connection.","b":"When sending a small text document to a neighbor.","c":"During load shedding, power outages, or in remote areas with zero internet signal.","d":"When you want to organize your desktop screen."}'::jsonb, 'c', 'Removable Media', 'Lesson 9', '2026-03-22T12:17:57.163Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597234', '69a6d7f3258e2632ad6e3719', 58, 'What does "Write Caching" do on a modern operating system?', '{"a":"It hides your files so no one else can read them.","b":"It writes data to the fast internal RAM first, telling you the transfer is complete before it has actually finished flushing the data to the USB drive.","c":"It automatically pays for your internet connection.","d":"It stops viruses from entering the USB drive."}'::jsonb, 'b', 'Write Caching', 'Lesson 9', '2026-03-22T12:17:57.164Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597238', '69a6d7f3258e2632ad6e3719', 62, 'Which of the following is considered physical removable storage?', '{"a":"Microsoft OneDrive","b":"A Solid State Drive (SSD) or Flash Drive","c":"A ZIP Archive","d":"The Master Index"}'::jsonb, 'b', 'Removable Storage Types', 'Lesson 9', '2026-03-22T12:17:57.165Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597240', '69a6d7f3258e2632ad6e3719', 70, 'What are the three pillars of digital organization discussed throughout the module?', '{"a":"Buying hardware, plugging it in, and turning it on.","b":"Structuring folders logically, naming files professionally, and storing data safely.","c":"Typing fast, using a mouse, and cleaning the screen.","d":"Browsing the web, sending emails, and watching videos."}'::jsonb, 'b', 'Three Pillars', 'Lesson 10', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597248', '69a6d7f3258e2632ad6e3719', 78, 'What does "GUI" stand for when we talk about the Windows File Explorer?', '{"a":"General User Internet","b":"Graphical User Interface (meaning you can click on pictures instead of typing code)","c":"Grand Unified Index","d":"Guided User Information"}'::jsonb, 'b', 'Graphical User Interface', 'Lesson 2', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597249', '69a6d7f3258e2632ad6e3719', 79, 'What is the main job of the Navigation Pane on the left side of File Explorer?', '{"a":"To play music files.","b":"To act as an elevator, letting you jump quickly between different major areas like \"Documents\" or \"Downloads.\"","c":"To delete all your files.","d":"To show the weather forecast."}'::jsonb, 'b', 'Navigation Pane', 'Lesson 2', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759724b', '69a6d7f3258e2632ad6e3719', 81, 'How do you select multiple files using the "Checkboxes" feature?', '{"a":"You turn on \"Item check boxes\" in the View menu and click the tiny box next to each file.","b":"You type a checkmark symbol on the keyboard.","c":"You drag the files to the desktop.","d":"You hold the spacebar."}'::jsonb, 'a', 'Checkboxes Selection', 'Lesson 2', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597255', '69a6d7f3258e2632ad6e3719', 91, 'What does the phrase "Building the fridge first" mean in computer filing?', '{"a":"It means you should store your laptop in a cold place.","b":"It means you should logically create your folders before you start saving your files, so your work has a proper home.","c":"It means you must buy new hardware.","d":"It means you should delete old files daily."}'::jsonb, 'b', 'Building the Fridge', 'Lesson 3', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759725c', '69a6d7f3258e2632ad6e3719', 98, 'What is the "Incinerator" trick (Shift + Delete)?', '{"a":"It creates a ZIP file.","b":"It completely bypasses the Recycle Bin, permanently destroying the file immediately.","c":"It copies the file ten times.","d":"It moves the file to the Cloud."}'::jsonb, 'b', 'Permanent Deletion', 'Lesson 4', '2026-03-22T12:17:57.170Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597263', '69a6d7f3258e2632ad6e3719', 105, 'What is the "Double-Extension Trick" used by hackers?', '{"a":"Saving a file twice.","b":"Naming a dangerous file something like Invoice.pdf.exe to trick you into thinking it is a harmless document instead of a malicious program.","c":"Making the file size twice as big.","d":"Zipping a folder inside another folder."}'::jsonb, 'b', 'Disguised Executables', 'Lesson 5', '2026-03-22T12:17:57.172Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597266', '69a6d7f3258e2632ad6e3719', 108, 'In OneDrive, what does a solid green circle with a white checkmark icon mean?', '{"a":"The file is online-only.","b":"The file has an error and cannot sync.","c":"The file is permanently downloaded to your physical device and will be available even if you lose internet access.","d":"The file is currently being deleted."}'::jsonb, 'c', 'Available Offline', 'Lesson 6', '2026-03-22T12:17:57.173Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597267', '69a6d7f3258e2632ad6e3719', 109, 'What does the blue cloud icon in OneDrive indicate?', '{"a":"The file is taking up space on your physical hard drive.","b":"The file is safely in the cloud, but you must have an active internet connection to open it.","c":"The file is a video.","d":"The file is infected with a virus."}'::jsonb, 'b', 'Online Only Icon', 'Lesson 6', '2026-03-22T12:17:57.173Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759726d', '69a6d7f3258e2632ad6e3719', 115, 'What is the difference between "Date Created" and "Date Modified"?', '{"a":"There is no difference.","b":"Date Created is when the file was born; Date Modified is the exact time someone last made a change and saved it.","c":"Date Modified is only used for pictures.","d":"Date Created changes every day."}'::jsonb, 'b', 'Timestamp Differences', 'Lesson 7', '2026-03-22T12:17:57.175Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759726e', '69a6d7f3258e2632ad6e3719', 116, 'If you want to find a file you worked on yesterday but can''t remember its name, what is the best tool to use?', '{"a":"The \"Date Modified\" filter in the search bar.","b":"The Recycle Bin.","c":"The \"Safely Remove Hardware\" tool.","d":"The Command Bar."}'::jsonb, 'a', 'Recent Files Filter', 'Lesson 7', '2026-03-22T12:17:57.175Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759726f', '69a6d7f3258e2632ad6e3719', 117, 'Why might searching "This PC" be a bad idea if you are in a rush?', '{"a":"It deletes the files it finds.","b":"It forces the computer to scan the entire massive hard drive, which can take a very long time.","c":"It only searches for pictures.","d":"It requires a USB drive."}'::jsonb, 'b', 'Global Search Lag', 'Lesson 7', '2026-03-22T12:17:57.175Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597276', '69a6d7f3258e2632ad6e3719', 124, 'What is the "Golden Rule" of using files that are inside a ZIP folder?', '{"a":"You should always edit them while they are still inside the ZIP folder.","b":"You must always \"Extract\" (unpack) the files out of the ZIP folder before you try to edit or work on them.","c":"You should rename the ZIP folder every time you open it.","d":"You must disconnect from the internet to open them."}'::jsonb, 'b', 'Unpacking Rule', 'Lesson 8', '2026-03-22T12:17:57.177Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759727c', '69a6d7f3258e2632ad6e3719', 130, 'Why are Solid State Drives (SSDs) much faster and more durable than HDDs?', '{"a":"Because they use a spinning metal disk.","b":"Because they rely entirely on the internet.","c":"Because they use instantaneous flash memory chips with zero moving parts to break.","d":"Because they are much heavier."}'::jsonb, 'c', 'Durability', 'Lesson 9', '2026-03-22T12:17:57.178Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597282', '69a6d7f3258e2632ad6e3719', 136, 'What is the 260-character limit known as in the Windows operating system?', '{"a":"The Storage Limit","b":"The MAX_PATH limit","c":"The Cloud Limit","d":"The Memory Cap"}'::jsonb, 'b', 'MAX_PATH cap', 'Lesson 10', '2026-03-22T12:17:57.180Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597283', '69a6d7f3258e2632ad6e3719', 137, 'What is the purpose of a "dummy file" during training?', '{"a":"To test a folder structure and practice moving data safely without risking real, important files.","b":"To permanently delete viruses.","c":"To trick the computer into running faster.","d":"To fill up the hard drive."}'::jsonb, 'a', 'Safe Testing', 'Lesson 10', '2026-03-22T12:17:57.180Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597284', '69a6d7f3258e2632ad6e3719', 138, 'If you create a folder named "2026-03-07_Project_Files", what standard are you following?', '{"a":"The CUA Standard","b":"The ISO 8601 Standard","c":"The Advanced Query Syntax Standard","d":"The SMTP Standard"}'::jsonb, 'b', 'Naming Conventions', 'Lesson 10', '2026-03-22T12:17:57.180Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597287', '69a6d7f3258e2632ad6e3719', 141, 'When you first turn on your computer, what software immediately goes to work as the "manager" to handle the screen, mouse, and memory?', '{"a":"The Microsoft Word program","b":"The Operating System","c":"The Cloud","d":"The ZIP archive"}'::jsonb, 'b', 'System Manager', 'Lesson 1', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597288', '69a6d7f3258e2632ad6e3719', 142, 'What is the primary cause of "The Search Trap" when using a computer?', '{"a":"Having too many physical screens connected.","b":"Saving all your files randomly and relying purely on your human memory to find them later.","c":"Using the internet too much.","d":"Organizing your files into clear, logical folders."}'::jsonb, 'b', 'Search Trap Causes', 'Lesson 1', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759728a', '69a6d7f3258e2632ad6e3719', 144, 'What does the term "digital data" refer to?', '{"a":"The physical plastic of the keyboard.","b":"Anything created or saved on a computer''s memory, like a typed letter, a photo, or an email.","c":"The electricity flowing from the wall.","d":"A specific brand of internet router."}'::jsonb, 'b', 'Digital Data Definition', 'Lesson 1', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759728e', '69a6d7f3258e2632ad6e3719', 148, 'If you want to jump straight from your "Downloads" folder to your "Pictures" folder in one single click, what tool on the left side of the screen should you use?', '{"a":"The Command Bar","b":"The Address Bar","c":"The Navigation Pane","d":"The Recycle Bin"}'::jsonb, 'c', 'Directory Jumping', 'Lesson 2', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759728f', '69a6d7f3258e2632ad6e3719', 149, 'What is the main, internal physical storage drive on a Windows computer universally called?', '{"a":"The A: Drive","b":"The Cloud Drive","c":"The C: Drive","d":"The USB Drive"}'::jsonb, 'c', 'System Drive Name', 'Lesson 2', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597293', '69a6d7f3258e2632ad6e3719', 153, 'What is the exact purpose of the "Quick Access" menu?', '{"a":"To automatically connect to the fastest Wi-Fi network.","b":"To test how fast you can type.","c":"To pin your favorite, daily-use folders to the very top so you do not have to search for them every morning.","d":"To permanently hide your files."}'::jsonb, 'c', 'Pinned Workflows', 'Lesson 2', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597295', '69a6d7f3258e2632ad6e3719', 155, 'What is the internationally accepted (ISO 8601) and professional way to write the date March 4, 2026, so a computer sorts it perfectly?', '{"a":"04-03-2026","b":"03-04-2026","c":"2026-03-04","d":"2026-04-03"}'::jsonb, 'c', 'Standardized Naming', 'Lesson 3', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597299', '69a6d7f3258e2632ad6e3719', 159, 'Why is "building the fridge first" (creating empty folders before starting a project) a highly recommended corporate habit?', '{"a":"It prevents the computer from overheating.","b":"It ensures your files have a safe, logical, structured home the very moment you click \"Save\" for the first time.","c":"It makes your internet connection faster.","d":"It hides the files from your boss."}'::jsonb, 'b', 'Home Before Work', 'Lesson 3', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759729c', '69a6d7f3258e2632ad6e3719', 162, 'If you use the "Copy" command on a legal document, what are you doing?', '{"a":"Creating a safe, identical duplicate for another location while leaving the original untouched.","b":"Deleting the original file.","c":"Sending the document directly to the printer.","d":"Renaming the document."}'::jsonb, 'a', 'Redundant Duplication', 'Lesson 4', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759729e', '69a6d7f3258e2632ad6e3719', 164, 'What happens if you Copy a document, but then you Copy a picture before you Paste the first document?', '{"a":"The computer will paste both of them at the same time.","b":"The first document is overwritten and erased from the Clipboard, replaced entirely by the picture.","c":"The computer will crash.","d":"The files will merge into one."}'::jsonb, 'b', 'Clipboard Replacement', 'Lesson 4', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972ab', '69a6d7f3258e2632ad6e3719', 177, 'What does the "Magic Mirror Effect" (Synchronization) mean in modern cloud storage?', '{"a":"Any change you make to a file on your laptop instantly and automatically happens to that exact file on your phone and tablet too.","b":"Your webcam turns on automatically.","c":"The screen reflects light to protect your eyes.","d":"Your files are copied to the desktop."}'::jsonb, 'a', 'Mirror Effect', 'Lesson 6', '2026-03-22T12:17:57.185Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972ae', '69a6d7f3258e2632ad6e3719', 180, 'What does a "Blue Cloud" icon mean next to a OneDrive file?', '{"a":"The file is a video.","b":"The file is safely on the internet, but you absolutely must have an active internet connection to open it.","c":"The file is shared with the public.","d":"The file is stored on a USB drive."}'::jsonb, 'b', 'Archived Online Icon', 'Lesson 6', '2026-03-22T12:17:57.186Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972af', '69a6d7f3258e2632ad6e3719', 181, 'How does the "Free Up Space" (Files On-Demand) trick specifically help users with small laptop hard drives?', '{"a":"It gives them free internet access.","b":"It allows them to see terabytes of archived files, but removes the heavy physical data from the laptop until the exact moment they double-click them.","c":"It permanently destroys old files.","d":"It blocks incoming emails."}'::jsonb, 'b', 'Space Reclamation', 'Lesson 6', '2026-03-22T12:17:57.186Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b7', '69a6d7f3258e2632ad6e3719', 189, 'What hidden, low-level system process runs constantly in the background to extract metadata for the search index?', '{"a":"The Recycle Bin","b":"SearchIndexer.exe","c":"Windows Defender","d":"The Command Prompt"}'::jsonb, 'b', 'Background Services', 'Lesson 7', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972ba', '69a6d7f3258e2632ad6e3719', 192, 'What does a ZIP archive physically do to a large folder of documents?', '{"a":"It translates the text into a different language.","b":"It structurally groups them into one clean package and mathematically shrinks their total physical weight.","c":"It changes all the files into PDFs.","d":"It uploads them to a public website."}'::jsonb, 'b', 'Structural Packaging', 'Lesson 8', '2026-03-22T12:17:57.189Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972bd', '69a6d7f3258e2632ad6e3719', 195, 'What is the "Golden Rule" before you start editing a document that you received inside a ZIP file?', '{"a":"You must rename the file first.","b":"You must completely Extract (unpack) the file out of the suitcase first, or your edits might be lost in a temporary cache.","c":"You must disconnect from the internet.","d":"You must print it out."}'::jsonb, 'b', 'Extraction Mandatory', 'Lesson 8', '2026-03-22T12:17:57.189Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c3', '69a6d7f3258e2632ad6e3719', 201, 'What will happen if you abruptly rip a USB drive out of the computer while the cache is still quietly transferring data in the background?', '{"a":"The screen will turn blue.","b":"The Master File Table (MFT) breaks, resulting in a permanently corrupted, unreadable file.","c":"The USB drive will catch fire.","d":"The computer will immediately reboot."}'::jsonb, 'b', 'Logical Link Breakdown', 'Lesson 9', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c5', '69a6d7f3258e2632ad6e3719', 203, 'Which USB connector is the modern, very fast, and oval-shaped standard that can be plugged in upside down?', '{"a":"USB-A","b":"USB-B","c":"USB-C","d":"USB-D"}'::jsonb, 'c', 'Reversible Connectors', 'Lesson 9', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c6', '69a6d7f3258e2632ad6e3719', 204, 'In Information Architecture, what does the 260-character MAX_PATH limit refer to?', '{"a":"The maximum number of files you can have on your computer.","b":"The maximum mathematical length of a file path; if you nest folders too deeply, the system will crash when trying to read or copy the data.","c":"The limit for writing an email.","d":"The maximum number of letters in a password."}'::jsonb, 'b', 'API Limits', 'Lesson 10', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972ca', '69a6d7f3258e2632ad6e3719', 208, 'What are the three core pillars of digital organization taught throughout Module 2?', '{"a":"Buying expensive hardware, plugging it in, and hoping it works.","b":"Browsing the internet, sending emails, and watching videos.","c":"Logic in structure, professionalism in naming, and security in storage.","d":"Typing fast, clicking quickly, and using a mouse."}'::jsonb, 'c', 'Organizational Pillars', 'Lesson 10', '2026-03-22T12:17:57.191Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972cb', '69a6d7f3258e2632ad6e3719', 209, 'If you build a digital filing system perfectly, what should you never have to rely on during a busy workday?', '{"a":"The computer''s screen.","b":"Your own human memory to remember the exact names of buried files.","c":"The keyboard.","d":"The mouse."}'::jsonb, 'b', 'Logic over Memory', 'Lesson 10', '2026-03-22T12:17:57.191Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972cc', '69a6d7f3258e2632ad6e3719', 210, 'What happens during a "High-Pressure Search Test" in a practical lab?', '{"a":"You have to type 100 words per minute.","b":"You turn off the computer by pulling the plug from the wall.","c":"You use the search bar and specific AQS commands to instantly isolate and locate test files buried deep in your new folder structure.","d":"You delete the entire operating system."}'::jsonb, 'c', 'Pressure Testing', 'Lesson 10', '2026-03-22T12:17:57.191Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275971fd', '69a6d7f3258e2632ad6e3719', 3, 'What happens to your files if you do not organize your digital data properly?', '{"a":"They will organize themselves automatically.","b":"They will be sent directly to the Cloud.","c":"They will become a chaotic mess and be hard to find.","d":"They will be permanently deleted by the computer."}'::jsonb, 'c', 'Organization', 'Lesson 1', '2026-03-22T12:17:57.142Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597202', '69a6d7f3258e2632ad6e3719', 8, 'What is the main tool in Windows used to look inside your digital filing cabinet?', '{"a":"Windows File Explorer","b":"The Calculator","c":"The Recycle Bin","d":"Microsoft Word"}'::jsonb, 'a', 'Windows File Explorer', 'Lesson 2', '2026-03-22T12:17:57.146Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597207', '69a6d7f3258e2632ad6e3719', 13, 'What symbol acts as a "wild card" in the search box to find every file of a certain type (like *.pdf)?', '{"a":"The underscore (_)","b":"The asterisk (*)","c":"The plus sign (+)","d":"The question mark (?)"}'::jsonb, 'b', 'Search Tool', 'Lesson 2', '2026-03-22T12:17:57.149Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597208', '69a6d7f3258e2632ad6e3719', 14, 'What does pinning a folder to "Quick Access" do?', '{"a":"It deletes the folder.","b":"It hides the folder from other users.","c":"It keeps your most used folders at the very top of the Navigation Pane for easy daily workflow.","d":"It automatically sends the folder to the Cloud."}'::jsonb, 'c', 'Quick Access', 'Lesson 2', '2026-03-22T12:17:57.149Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759720d', '69a6d7f3258e2632ad6e3719', 19, 'What keyboard shortcut instantly allows you to rename a highlighted file with professional speed?', '{"a":"F1","b":"F2","c":"F5","d":"F10"}'::jsonb, 'b', 'Rename Shortcut', 'Lesson 3', '2026-03-22T12:17:57.151Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597211', '69a6d7f3258e2632ad6e3719', 23, 'What happens to the original file when you use the "Cut" command (moving data)?', '{"a":"It stays exactly where it is.","b":"It is duplicated three times.","c":"It is removed from its original location and placed in the new location.","d":"It is permanently destroyed."}'::jsonb, 'c', 'Moving Data (Cut)', 'Lesson 4', '2026-03-22T12:17:57.154Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597213', '69a6d7f3258e2632ad6e3719', 25, 'Which keyboard shortcut is the global standard for copying data safely?', '{"a":"Ctrl + X","b":"Ctrl + C","c":"Ctrl + V","d":"Ctrl + Z"}'::jsonb, 'b', 'Copy Shortcut', 'Lesson 4', '2026-03-22T12:17:57.155Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597215', '69a6d7f3258e2632ad6e3719', 27, 'What is the primary purpose of the Recycle Bin?', '{"a":"To permanently destroy files immediately.","b":"To act as a safety net so you can rescue a file you accidentally deleted.","c":"To store your favorite pictures.","d":"To clean viruses off your computer."}'::jsonb, 'b', 'Recycle Bin', 'Lesson 4', '2026-03-22T12:17:57.155Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597219', '69a6d7f3258e2632ad6e3719', 31, 'Which of the following file extensions is highly dangerous and should never be opened from an unsolicited email?', '{"a":".jpg","b":".docx","c":".exe","d":".pdf"}'::jsonb, 'c', 'Malicious Extensions', 'Lesson 5', '2026-03-22T12:17:57.157Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759721c', '69a6d7f3258e2632ad6e3719', 34, 'What feature allows users to customize their workflow by permanently mapping a file extension to their preferred app?', '{"a":"Changing Default Apps","b":"Hiding extensions","c":"The Recycle Bin","d":"The Navigation Pane"}'::jsonb, 'a', 'Default Applications', 'Lesson 5', '2026-03-22T12:17:57.158Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597221', '69a6d7f3258e2632ad6e3719', 39, 'What does the "Files On-Demand" (Free Up Space) feature solve?', '{"a":"It gives you a faster internet connection.","b":"It lets you see massive amounts of Cloud data on your small hard drive without actually downloading the heavy files until you click them.","c":"It stops your computer from needing a battery.","d":"It prints your documents without a cable."}'::jsonb, 'b', 'Files On-Demand', 'Lesson 6', '2026-03-22T12:17:57.159Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597227', '69a6d7f3258e2632ad6e3719', 45, 'If you want to search strictly for pictures, which search syntax would you use?', '{"a":"find:pictures","b":"ext:docx","c":"type:image","d":"open:photo"}'::jsonb, 'c', 'Image Search', 'Lesson 7', '2026-03-22T12:17:57.161Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759722b', '69a6d7f3258e2632ad6e3719', 49, 'What metadata does the computer''s indexer extract to make searching fast?', '{"a":"The file''s exact physical weight.","b":"The date, author, and file extension.","c":"The color of the screen.","d":"The brand of the computer."}'::jsonb, 'b', 'Metadata Extraction', 'Lesson 7', '2026-03-22T12:17:57.162Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759722c', '69a6d7f3258e2632ad6e3719', 50, 'What is the hard, unforgiving limit for incoming and outgoing email attachments on most standard servers?', '{"a":"1 Gigabyte (GB)","b":"25 Megabytes (MB)","c":"500 Kilobytes (KB)","d":"100 Megabytes (MB)"}'::jsonb, 'b', 'Email Size Limits', 'Lesson 8', '2026-03-22T12:17:57.162Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759722d', '69a6d7f3258e2632ad6e3719', 51, 'What will happen if you try to send an email attachment that is 30 MB in size?', '{"a":"The server will actively bounce the message back with an NDR (Non-Delivery Report) error.","b":"The email will go through, but it will take a week to arrive.","c":"The email system will automatically delete half of your files.","d":"The computer will crash."}'::jsonb, 'a', 'NDR Errors', 'Lesson 8', '2026-03-22T12:17:57.162Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597241', '69a6d7f3258e2632ad6e3719', 71, 'In the digital office metaphor, what does the computer''s hard drive represent?', '{"a":"The office desk","b":"A massive, multi-level metal filing cabinet","c":"The trash can","d":"The telephone"}'::jsonb, 'b', 'Hard Drive Metaphor', 'Lesson 1', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597242', '69a6d7f3258e2632ad6e3719', 72, 'What are the individual, tangible pieces of work (like a letter or a photo) you create on a computer called?', '{"a":"Hardware","b":"Folders","c":"Files","d":"Monitors"}'::jsonb, 'c', 'Individual Files', 'Lesson 1', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597244', '69a6d7f3258e2632ad6e3719', 74, 'If you save all of your files directly onto your Desktop without using any folders, what will eventually happen?', '{"a":"The computer will automatically sort them for you.","b":"The screen will become cluttered, chaotic, and stressful to look at.","c":"The files will be sent to the Recycle Bin.","d":"The Desktop will become completely invisible."}'::jsonb, 'b', 'Desktop Clutter', 'Lesson 1', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597247', '69a6d7f3258e2632ad6e3719', 77, 'Which of the following is true about "The Cloud" as mentioned in Lesson 1?', '{"a":"It is a physical piece of hardware you plug into your computer.","b":"It is an internet-based safe storage area that protects your files from physical computer damage.","c":"It is the program used to type letters.","d":"It only works on cloudy days."}'::jsonb, 'b', 'The Cloud', 'Lesson 1', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759724a', '69a6d7f3258e2632ad6e3719', 80, 'What does the "C: Drive" represent on a standard Windows computer?', '{"a":"The Cloud storage account.","b":"A temporary USB flash drive.","c":"The main, internal physical hard drive where Windows and all your files live.","d":"The CD-ROM player."}'::jsonb, 'c', 'Internal Hard Drive', 'Lesson 2', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597250', '69a6d7f3258e2632ad6e3719', 86, 'Which of the following characters is completely safe to use when naming a file?', '{"a":"A question mark (?)","b":"A forward slash (/)","c":"A hyphen (-)","d":"A colon (:)"}'::jsonb, 'c', 'Safe Characters', 'Lesson 3', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597252', '69a6d7f3258e2632ad6e3719', 88, 'Why does the international ISO 8601 standard put the Year first (YYYY-MM-DD) instead of the Day?', '{"a":"Because it looks prettier.","b":"Because it forces computer systems globally to sort the files in perfect, unbroken chronological order.","c":"Because Americans write it that way.","d":"Because the computer''s clock is backwards."}'::jsonb, 'b', 'Chronological Sorting', 'Lesson 3', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597256', '69a6d7f3258e2632ad6e3719', 92, 'If you want to keep your original file safely in your "Documents" folder but give an exact duplicate to a friend on a USB stick, which command should you use?', '{"a":"Cut","b":"Delete","c":"Copy","d":"Rename"}'::jsonb, 'c', 'Data Redundancy', 'Lesson 4', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597258', '69a6d7f3258e2632ad6e3719', 94, 'Where does your data temporarily live while it is waiting for you to press "Paste"?', '{"a":"In the Recycle Bin","b":"On the internet","c":"In the Clipboard","d":"In the Command Bar"}'::jsonb, 'c', 'Memory Holding Area', 'Lesson 4', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759725b', '69a6d7f3258e2632ad6e3719', 97, 'What is the keyboard shortcut to physically "Cut" a file?', '{"a":"Ctrl + C","b":"Ctrl + X","c":"Ctrl + P","d":"Ctrl + Z"}'::jsonb, 'b', 'Cut Shortcut', 'Lesson 4', '2026-03-22T12:17:57.170Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759725d', '69a6d7f3258e2632ad6e3719', 99, 'What does the file extension tell the computer''s operating system?', '{"a":"How much the file costs.","b":"What specific type of file it is and which program should be used to open it.","c":"Who created the file.","d":"How many words are in the file."}'::jsonb, 'b', 'System Identification', 'Lesson 5', '2026-03-22T12:17:57.170Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597260', '69a6d7f3258e2632ad6e3719', 102, 'Which file extension represents an audio file, like a song or a voice recording?', '{"a":".mp3","b":".jpg","c":".xlsx","d":".docx"}'::jsonb, 'a', 'Audio Extension', 'Lesson 5', '2026-03-22T12:17:57.171Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597261', '69a6d7f3258e2632ad6e3719', 103, 'By default, why does Windows hide the file extensions from the user?', '{"a":"To make the files run faster.","b":"Because it assumes everyday users do not need to see them, and to prevent users from accidentally deleting the extension and breaking the file.","c":"Because they take up too much memory.","d":"Because the internet requires them to be hidden."}'::jsonb, 'b', 'Hidden Extensions', 'Lesson 5', '2026-03-22T12:17:57.172Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597264', '69a6d7f3258e2632ad6e3719', 106, 'Who usually owns the massive physical server farms where Cloud data is securely stored?', '{"a":"Local municipalities.","b":"Massive tech companies like Microsoft (OneDrive) or Google (Google Drive).","c":"The user''s internet service provider.","d":"The computer manufacturer."}'::jsonb, 'b', 'Server Farms', 'Lesson 6', '2026-03-22T12:17:57.173Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597265', '69a6d7f3258e2632ad6e3719', 107, 'What happens if you delete a synchronized file from your OneDrive folder on your laptop?', '{"a":"It is only deleted from the laptop, but stays in the Cloud.","b":"The magic mirror effect means it is instantly deleted from the Cloud and all your other connected devices.","c":"The file turns into a ZIP folder.","d":"The computer stops working."}'::jsonb, 'b', 'Cloud Deletion', 'Lesson 6', '2026-03-22T12:17:57.173Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597269', '69a6d7f3258e2632ad6e3719', 111, 'What does the "Version History" feature in OneDrive allow you to do?', '{"a":"See who bought your computer.","b":"Right-click a file and restore an older version of it if you accidentally ruined the document earlier that day.","c":"Change the language of the computer.","d":"Delete all your files at once."}'::jsonb, 'b', 'Version Recovery', 'Lesson 6', '2026-03-22T12:17:57.174Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597271', '69a6d7f3258e2632ad6e3719', 119, 'What does AQS stand for when searching for files?', '{"a":"Automatic Question System","b":"Advanced Query Syntax","c":"Always Quick Search","d":"Authorized Query Service"}'::jsonb, 'b', 'Search Cheat Codes', 'Lesson 7', '2026-03-22T12:17:57.176Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597274', '69a6d7f3258e2632ad6e3719', 122, 'If an email server bounces your message back with an NDR, what does NDR mean?', '{"a":"No Data Received","b":"Non-Delivery Report (an error saying your file was blocked because it was too large)","c":"Network Down Report","d":"New Document Required"}'::jsonb, 'b', 'Delivery Failure', 'Lesson 8', '2026-03-22T12:17:57.177Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597280', '69a6d7f3258e2632ad6e3719', 134, 'What are the "Three Pillars of Digital Organization" discussed in the practical lab?', '{"a":"Logic in structure, professionalism in naming, and security in storage.","b":"Buying a mouse, buying a keyboard, and buying a screen.","c":"Typing fast, using the internet, and sending emails.","d":"Downloading files, deleting files, and hiding files."}'::jsonb, 'a', 'Organizational Pillars', 'Lesson 10', '2026-03-22T12:17:57.179Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597286', '69a6d7f3258e2632ad6e3719', 140, 'If you wanted to test your new filing system under pressure, what would you do?', '{"a":"Delete all the files immediately.","b":"Use the search bar to locate specific test files buried inside the folders using AQS commands.","c":"Turn the computer off by pulling the plug.","d":"Change the language to French."}'::jsonb, 'b', 'Validation Testing', 'Lesson 10', '2026-03-22T12:17:57.180Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759728b', '69a6d7f3258e2632ad6e3719', 145, 'If you accidentally drag an important folder into the wrong place and it disappears, what is the fastest way to get it back?', '{"a":"Turn the computer off immediately.","b":"Press the universal \"Undo\" shortcut: Ctrl + Z.","c":"Buy a new hard drive.","d":"Empty the Recycle Bin."}'::jsonb, 'b', 'Fast Recovery', 'Lesson 1', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759728c', '69a6d7f3258e2632ad6e3719', 146, 'What is the primary benefit of "Nesting" your digital folders?', '{"a":"It makes the computer run mathematically faster.","b":"It allows you to create a clean, logical path—like having dividers inside a filing cabinet drawer.","c":"It stops you from using the internet.","d":"It instantly deletes old work to save space."}'::jsonb, 'b', 'Drawer Metaphor', 'Lesson 1', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759728d', '69a6d7f3258e2632ad6e3719', 147, 'In Windows 11, what do you see at the top of File Explorer instead of the old text words like "Copy" and "Paste"?', '{"a":"A blank black screen.","b":"Clean, modern picture icons.","c":"A list of all your passwords.","d":"The weather forecast."}'::jsonb, 'b', 'Modern Interface', 'Lesson 2', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597291', '69a6d7f3258e2632ad6e3719', 151, 'If you want to visually see what a photo looks like before you double-click to open it, which View should you choose?', '{"a":"Details View","b":"Small Icons View","c":"Extra Large Icons View","d":"List View"}'::jsonb, 'c', 'Media Previews', 'Lesson 2', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597294', '69a6d7f3258e2632ad6e3719', 154, 'What will the Windows operating system do if you try to save a file named Report:Final??', '{"a":"It will completely block you from saving it because colons and question marks are deeply reserved for system code.","b":"It will save the file normally.","c":"It will upload the file to the Cloud.","d":"It will print the file automatically."}'::jsonb, 'a', 'Illegal Symbols Handling', 'Lesson 3', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597298', '69a6d7f3258e2632ad6e3719', 158, 'What does the F2 key do when you click on a file once to highlight it?', '{"a":"It deletes the file instantly.","b":"It opens the help menu.","c":"It instantly highlights the text of the file''s name so you can type a new one with professional speed.","d":"It opens the file in a new window."}'::jsonb, 'c', 'Rename Key', 'Lesson 3', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759729a', '69a6d7f3258e2632ad6e3719', 160, 'What is a "File Path"?', '{"a":"The cable connecting your computer to the wall.","b":"The specific text route the computer takes through your folders to find a piece of data.","c":"The process of copying a file to a USB drive.","d":"The password used to unlock your computer."}'::jsonb, 'b', 'File Path Definition', 'Lesson 10', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759729f', '69a6d7f3258e2632ad6e3719', 165, 'What is the universal CUA keyboard shortcut used for Copying data safely?', '{"a":"Ctrl + C","b":"Ctrl + X","c":"Ctrl + P","d":"Ctrl + Z"}'::jsonb, 'a', 'CUA Copy', 'Lesson 4', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a2', '69a6d7f3258e2632ad6e3719', 168, 'If you hold down the Ctrl key while dragging a file with your mouse, you will see a tiny green Plus (+) sign. What does this mean?', '{"a":"The computer is going to add the file to the Recycle Bin.","b":"The computer is going to safely copy the file instead of moving it.","c":"The computer is going to make the file size larger.","d":"The computer will open the file immediately."}'::jsonb, 'b', 'Forced Drag Copy', 'Lesson 4', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a6', '69a6d7f3258e2632ad6e3719', 172, 'Why are government security organizations (like CISA) so worried about unsolicited .exe files?', '{"a":"Because they take up too much hard drive space.","b":"Because they are executable programs that frequently carry malware, spyware, or ransomware into your system.","c":"Because they cost money to open.","d":"Because they only work on Apple computers."}'::jsonb, 'b', 'CISA Executable Warning', 'Lesson 5', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a9', '69a6d7f3258e2632ad6e3719', 175, 'Why do cybercriminals frequently send emails with files named "Invoice.pdf.exe"?', '{"a":"To make the file easier to read.","b":"To compress the file size.","c":"To trick the user into thinking it is a safe PDF document, hiding the dangerous .exe program at the very end.","d":"Because it is required by the email server."}'::jsonb, 'c', 'Phishing Disguise Trick', 'Lesson 5', '2026-03-22T12:17:57.185Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972aa', '69a6d7f3258e2632ad6e3719', 176, 'When you save a file to Microsoft OneDrive, where is the physical data actually stored?', '{"a":"On your local Wi-Fi router.","b":"In massive, highly secure physical server farms owned by Microsoft.","c":"Inside the computer''s battery.","d":"On a hidden USB drive."}'::jsonb, 'b', 'Off-site Physical Location', 'Lesson 6', '2026-03-22T12:17:57.185Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b3', '69a6d7f3258e2632ad6e3719', 185, 'If you want to search exclusively for a PDF file inside a messy folder, what specific AQS command should you type in the search bar?', '{"a":"open:pdf","b":"name:pdf","c":"ext:pdf","d":"find:pdf"}'::jsonb, 'c', 'Explicit Extension Search', 'Lesson 7', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972bc', '69a6d7f3258e2632ad6e3719', 194, 'Is a standard ZIP file destructive? Will it lower the quality of a high-resolution family photo?', '{"a":"Yes, ZIP files always compress destructively.","b":"No, ZIP compression is strictly lossless; the exact byte-for-byte data is perfectly restored when unpacked.","c":"Only if you email the ZIP file.","d":"Yes, it converts photos to black and white."}'::jsonb, 'b', 'Lossless Guarantee', 'Lesson 8', '2026-03-22T12:17:57.189Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c1', '69a6d7f3258e2632ad6e3719', 199, 'Why is a modern SSD (Solid State Drive) much faster and safer to travel with than an older HDD?', '{"a":"An SSD uses the internet to run.","b":"An SSD uses instant flash memory chips with zero moving physical parts to break during travel.","c":"An SSD is physically much heavier.","d":"An SSD automatically encrypts all files."}'::jsonb, 'b', 'Mechanical Parts Risk', 'Lesson 9', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c7', '69a6d7f3258e2632ad6e3719', 205, 'What is the best architectural strategy to avoid the catastrophic MAX_PATH error when organizing your files?', '{"a":"Keep your folder structures broad and shallow, rather than narrow and deeply nested.","b":"Use all capital letters when naming files.","c":"Never use folders at all.","d":"Save everything directly to the desktop."}'::jsonb, 'a', 'Broad vs Shallow', 'Lesson 10', '2026-03-22T12:17:57.191Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275971fe', '69a6d7f3258e2632ad6e3719', 4, 'What does the term "nesting" refer to in computer filing?', '{"a":"Putting a file into the Recycle Bin.","b":"Putting folders inside of other folders.","c":"Connecting to the internet.","d":"Changing a file''s name."}'::jsonb, 'b', 'Nesting', 'Lesson 1', '2026-03-22T12:17:57.143Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597200', '69a6d7f3258e2632ad6e3719', 6, 'Why is it a good professional habit to use an underscore (_) instead of a blank space when naming a folder?', '{"a":"It makes the computer run much faster.","b":"It saves physical hard drive space.","c":"The internet and email systems sometimes break links that have blank spaces.","d":"It prevents the file from being deleted."}'::jsonb, 'c', 'Naming Habits', 'Lesson 1', '2026-03-22T12:17:57.144Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597203', '69a6d7f3258e2632ad6e3719', 9, 'In File Explorer, what acts as your digital GPS route to show exactly where you are?', '{"a":"The Command Bar","b":"The Navigation Pane","c":"The Address Bar","d":"The Quick Access menu"}'::jsonb, 'c', 'Address Bar', 'Lesson 2', '2026-03-22T12:17:57.146Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597205', '69a6d7f3258e2632ad6e3719', 11, 'Which tool provides a "training wheels" approach for safely selecting multiple files using the mouse?', '{"a":"Item check boxes","b":"The Address Bar","c":"The Details view","d":"The command prompt"}'::jsonb, 'a', 'Item Check Boxes', 'Lesson 2', '2026-03-22T12:17:57.148Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759720f', '69a6d7f3258e2632ad6e3719', 21, 'Why is having a legally sound audit trail of document revisions important in a corporate team?', '{"a":"It keeps track of exactly who changed what, and in what order.","b":"It hides the documents from the boss.","c":"It stops the computer from needing updates.","d":"It shrinks the size of the documents."}'::jsonb, 'a', 'Audit Trails', 'Lesson 3', '2026-03-22T12:17:57.152Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597214', '69a6d7f3258e2632ad6e3719', 26, 'Which keyboard shortcut is the global standard for pasting data?', '{"a":"Ctrl + P","b":"Ctrl + V","c":"Ctrl + C","d":"Ctrl + X"}'::jsonb, 'b', 'Paste Shortcut', 'Lesson 4', '2026-03-22T12:17:57.155Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597216', '69a6d7f3258e2632ad6e3719', 28, 'If you want to force a file to be copied (instead of moved) while dragging it with your mouse, what hidden symbol should you look for?', '{"a":"A red X","b":"A green arrow","c":"A small Plus (+) sign","d":"A question mark"}'::jsonb, 'c', 'Drag and Copy', 'Lesson 4', '2026-03-22T12:17:57.156Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759721d', '69a6d7f3258e2632ad6e3719', 35, 'Why do hackers sometimes use a "Double-Extension Trick" (like report.pdf.exe)?', '{"a":"To make the file open faster.","b":"To try and trick the user into thinking a dangerous program is just a harmless document.","c":"To save the file in two different places at once.","d":"To automatically print the document."}'::jsonb, 'b', 'Double Extension Trick', 'Lesson 5', '2026-03-22T12:17:57.158Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759721e', '69a6d7f3258e2632ad6e3719', 36, 'When you save a file to "The Cloud," where does the physical data actually go?', '{"a":"It floats in the air above the computer.","b":"It is stored inside the computer''s internal processor.","c":"It is sent over the internet to massive, highly secure server farms owned by companies like Microsoft or Google.","d":"It is stored on a local USB flash drive."}'::jsonb, 'c', 'Cloud Storage', 'Lesson 6', '2026-03-22T12:17:57.159Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759721f', '69a6d7f3258e2632ad6e3719', 37, 'What is the magic "Synchronization" mirror effect in Cloud storage?', '{"a":"Whatever you do to a file on one device instantly happens to that exact same file across all your connected devices.","b":"The file copies itself until the hard drive is full.","c":"The screen reflects your face.","d":"The computer locks the file so no one can read it."}'::jsonb, 'a', 'Synchronization', 'Lesson 6', '2026-03-22T12:17:57.159Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597225', '69a6d7f3258e2632ad6e3719', 43, 'How does the computer search for files so quickly when you use the Search Bar?', '{"a":"It physically scans every single inch of the hard drive every time you press Enter.","b":"It reads a centralized, highly optimized database called the \"Master Index\" that runs quietly in the background.","c":"It asks the internet to find the file.","d":"It guesses where the file might be."}'::jsonb, 'b', 'Master Index', 'Lesson 7', '2026-03-22T12:17:57.160Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597229', '69a6d7f3258e2632ad6e3719', 47, 'Which special software components allow Windows to read the text inside a PDF or Word document during a deep search?', '{"a":"The Recycle Bin","b":"iFilters","c":"The Clipboard","d":"The Address Bar"}'::jsonb, 'b', 'iFilters', 'Lesson 7', '2026-03-22T12:17:57.161Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597231', '69a6d7f3258e2632ad6e3719', 55, 'Why is grouping files into a ZIP folder referred to as creating a "Digital Suitcase"?', '{"a":"Because it makes multiple separate files travel cleanly together as one single package.","b":"Because you need to pay extra to send it.","c":"Because it requires a password to open.","d":"Because it only works on laptops."}'::jsonb, 'a', 'Digital Suitcase', 'Lesson 8', '2026-03-22T12:17:57.163Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597235', '69a6d7f3258e2632ad6e3719', 59, 'If you rip a USB drive out of the computer before the cache is fully flushed, what happens?', '{"a":"The internet will disconnect.","b":"The file system metadata breaks, resulting in a corrupted, ruined file.","c":"The computer will print a warning page.","d":"The USB drive will catch fire."}'::jsonb, 'b', 'Data Corruption', 'Lesson 9', '2026-03-22T12:17:57.164Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597236', '69a6d7f3258e2632ad6e3719', 60, 'What strict protocol must you follow before unplugging an external drive?', '{"a":"Turn off the computer screen.","b":"Use the \"Safely Remove Hardware\" option.","c":"Delete all the files on the drive.","d":"Disconnect your mouse and keyboard."}'::jsonb, 'b', 'Eject Protocol', 'Lesson 9', '2026-03-22T12:17:57.164Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597237', '69a6d7f3258e2632ad6e3719', 61, 'What does the "Safely Remove Hardware" command actively tell the operating system to do?', '{"a":"Forcefully flush all pending data to the drive and cut the software power connection securely.","b":"Format the drive and erase everything on it.","c":"Send an email to the administrator.","d":"Zip all the files on the drive."}'::jsonb, 'a', 'System Unmounting', 'Lesson 9', '2026-03-22T12:17:57.165Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759723c', '69a6d7f3258e2632ad6e3719', 66, 'What is the fundamental rule of Information Architecture when creating folders?', '{"a":"Keep your systems narrow and deep.","b":"Keep your systems broad and shallow.","c":"Put all your files on the desktop.","d":"Never use capital letters."}'::jsonb, 'b', 'Information Architecture', 'Lesson 10', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759723d', '69a6d7f3258e2632ad6e3719', 67, 'What ensures that your files will sort chronologically, regardless of what local language a computer is running?', '{"a":"Putting a number 1 at the start of every file.","b":"Using the internationally recognized ISO 8601 strict date format (YYYY-MM-DD).","c":"Saving everything as a PDF.","d":"Using the \"Safely Remove Hardware\" tool."}'::jsonb, 'b', 'International Standards', 'Lesson 10', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597243', '69a6d7f3258e2632ad6e3719', 73, 'What is the primary purpose of creating a folder on your computer?', '{"a":"To make the computer run faster.","b":"To group related files together so they are easy to find and manage.","c":"To connect to the Wi-Fi.","d":"To permanently delete old documents."}'::jsonb, 'b', 'Folder Purpose', 'Lesson 1', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597245', '69a6d7f3258e2632ad6e3719', 75, 'What happens when you hold down the Ctrl key and press the letter Z?', '{"a":"The computer shuts down.","b":"You instantly reverse or \"Undo\" your last accidental mistake.","c":"You create a new file.","d":"You connect to a printer."}'::jsonb, 'b', 'Undo Shortcut', 'Lesson 1', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759724c', '69a6d7f3258e2632ad6e3719', 82, 'If you need to quickly figure out which file is taking up the most space on your computer, what should you do in File Explorer?', '{"a":"Click the \"Date Modified\" column.","b":"Switch to the Details view and click the \"Size\" column header to sort them from largest to smallest.","c":"Look at the Extra Large Icons.","d":"Rename the files."}'::jsonb, 'b', 'Sorting by Size', 'Lesson 2', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759724d', '69a6d7f3258e2632ad6e3719', 83, 'In Windows 11, what major change happened to the Command Bar at the top of File Explorer compared to Windows 10?', '{"a":"The Command Bar was removed entirely.","b":"Words like \"Copy\" and \"Paste\" were replaced by clean, modern icons (pictures).","c":"The Command Bar only works if you have the internet.","d":"It now requires a password to use."}'::jsonb, 'b', 'Windows 11 Icons', 'Lesson 2', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759724e', '69a6d7f3258e2632ad6e3719', 84, 'What happens when you sort your files by "Date Modified"?', '{"a":"It changes the calendar on your computer.","b":"It arranges your files so the ones you worked on most recently are exactly at the top.","c":"It deletes files older than one year.","d":"It renames the files to today''s date."}'::jsonb, 'b', 'Date Modified Sorting', 'Lesson 2', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597259', '69a6d7f3258e2632ad6e3719', 95, 'Does the Clipboard hold your copied data forever?', '{"a":"Yes, it never deletes it.","b":"No, it only holds it temporarily; if you copy something else, the first item is usually overwritten and lost.","c":"Yes, it saves it to a permanent folder.","d":"No, it deletes it after exactly 5 seconds."}'::jsonb, 'b', 'Clipboard Volatility', 'Lesson 4', '2026-03-22T12:17:57.170Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759725f', '69a6d7f3258e2632ad6e3719', 101, 'Which file extension represents a universal document that looks exactly the same on every device, like a digital piece of printed paper?', '{"a":".txt","b":".pdf","c":".mp4","d":".zip"}'::jsonb, 'b', 'PDF Extension', 'Lesson 5', '2026-03-22T12:17:57.171Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597262', '69a6d7f3258e2632ad6e3719', 104, 'If you double-click a file and it opens in the wrong program, what should you do?', '{"a":"Delete the file immediately.","b":"Right-click the file and choose \"Open With\" to select the correct program.","c":"Unplug your computer.","d":"Change the file''s name."}'::jsonb, 'b', 'Open With Utility', 'Lesson 5', '2026-03-22T12:17:57.172Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597268', '69a6d7f3258e2632ad6e3719', 110, 'Why is sharing a Cloud link considered much safer than sending an actual file as an email attachment?', '{"a":"Because links are smaller and you can revoke the person''s access to the document at any time if you change your mind.","b":"Because links don''t require the internet.","c":"Because attachments always contain viruses.","d":"Because attachments cannot be opened on a Mac."}'::jsonb, 'a', 'Revocable Links', 'Lesson 6', '2026-03-22T12:17:57.174Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759726a', '69a6d7f3258e2632ad6e3719', 112, 'Why do IT professionals consider the Cloud the best defense against catastrophic data loss?', '{"a":"Because it is completely immune to human error.","b":"Because the data is stored completely off-site, protecting it from local fires, theft, and hardware failure.","c":"Because it prints the files automatically.","d":"Because it stops you from using USB drives forever."}'::jsonb, 'b', 'Off-site Security', 'Lesson 6', '2026-03-22T12:17:57.174Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759726c', '69a6d7f3258e2632ad6e3719', 114, 'If you are looking for a massive video file to delete, which Search Syntax would you use?', '{"a":"ext:docx","b":"type:image","c":"size:gigantic","d":"open:video"}'::jsonb, 'c', 'Gigantic Search', 'Lesson 7', '2026-03-22T12:17:57.175Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597270', '69a6d7f3258e2632ad6e3719', 118, 'What do iFilters allow the Windows search bar to do?', '{"a":"Take pictures of your screen.","b":"Mathematically break open a document and read the specific words written on the pages inside.","c":"Clean the computer''s memory.","d":"Stop viruses."}'::jsonb, 'b', 'Deep Search', 'Lesson 7', '2026-03-22T12:17:57.175Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597273', '69a6d7f3258e2632ad6e3719', 121, 'What does SMTP stand for in the context of email limits?', '{"a":"Simple Mail Transfer Protocol","b":"Standard Memory Transmission Process","c":"Secure Message Text Program","d":"System Mail Transfer Process"}'::jsonb, 'a', 'SMTP Protocols', 'Lesson 8', '2026-03-22T12:17:57.176Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597275', '69a6d7f3258e2632ad6e3719', 123, 'How does the DEFLATE algorithm mathematically shrink a file?', '{"a":"It cuts the edges off your pictures.","b":"It deletes the second half of your document.","c":"It replaces large, repeating binary patterns with tiny mathematical shortcuts.","d":"It changes the colors to black and white."}'::jsonb, 'c', 'Dictionary Encoding', 'Lesson 8', '2026-03-22T12:17:57.177Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597277', '69a6d7f3258e2632ad6e3719', 125, 'Does unzipping a file cost money or require special paid software on Windows 11?', '{"a":"Yes, you must always buy third-party software.","b":"No, the ability to create and extract ZIP files is built completely free into the core of Windows 11.","c":"Only if the file is larger than 1GB.","d":"Yes, you have to pay per file."}'::jsonb, 'b', 'Native Compression', 'Lesson 8', '2026-03-22T12:17:57.177Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597278', '69a6d7f3258e2632ad6e3719', 126, 'What happens if you try to edit a Word document while it is still locked inside a ZIP suitcase?', '{"a":"The document will save perfectly.","b":"The computer might crash or your changes will be permanently lost into a temporary folder when you close the file.","c":"The document will automatically upload to the Cloud.","d":"The ZIP file will change its name."}'::jsonb, 'b', 'Temporary Folders Loss', 'Lesson 8', '2026-03-22T12:17:57.177Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597279', '69a6d7f3258e2632ad6e3719', 127, 'What is an "Air Gap" in computer security?', '{"a":"A space between the keyboard keys.","b":"A situation where a computer has zero connection to the internet or any other network for absolute maximum security.","c":"A type of cloud storage.","d":"A broken Wi-Fi router."}'::jsonb, 'b', 'Air Gapping', 'Lesson 9', '2026-03-22T12:17:57.178Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759727e', '69a6d7f3258e2632ad6e3719', 132, 'What happens to the Master File Table (MFT) if you rip a USB out while the cache is still writing?', '{"a":"It gets upgraded.","b":"It breaks, resulting in a corrupted file that cannot be opened.","c":"It moves to the cloud.","d":"It locks the drive with a password."}'::jsonb, 'b', 'MFT Corruption', 'Lesson 9', '2026-03-22T12:17:57.179Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597285', '69a6d7f3258e2632ad6e3719', 139, 'Why is hands-on practice (like a lab) more effective than just reading theory about file management?', '{"a":"It forces the computer to update.","b":"It converts theoretical head-knowledge into permanent muscle memory.","c":"It makes the files smaller.","d":"It bypasses the need for an internet connection."}'::jsonb, 'b', 'Muscle Memory', 'Lesson 10', '2026-03-22T12:17:57.180Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597289', '69a6d7f3258e2632ad6e3719', 143, 'Why is it a fantastic professional habit to use CamelCase (like CourseWork) or an underscore (like Course_Work) when naming a folder?', '{"a":"It stops viruses from entering the folder.","b":"It saves battery power on your laptop.","c":"It ensures the name never \"breaks\" or turns into ugly code (%20) if you email it or upload it to the internet.","d":"It automatically encrypts the folder."}'::jsonb, 'c', 'Web-Safe Naming', 'Lesson 1', '2026-03-22T12:17:57.181Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597292', '69a6d7f3258e2632ad6e3719', 152, 'If you want to mathematically sort your files from the biggest size to the smallest size to free up space, which View must you be in?', '{"a":"Extra Large Icons View","b":"Details View","c":"Hidden View","d":"Web View"}'::jsonb, 'b', 'Analytical Sorting', 'Lesson 2', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597296', '69a6d7f3258e2632ad6e3719', 156, 'What is the primary problem with naming a file "Final_Report_Edited_Real_Final"?', '{"a":"The file becomes too large to email.","b":"It creates a messy, confusing system where nobody in a corporate team knows which file is actually the newest.","c":"It automatically deletes older versions.","d":"The internet cannot read the word \"Final\"."}'::jsonb, 'b', 'Vague Identification', 'Lesson 3', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597297', '69a6d7f3258e2632ad6e3719', 157, 'What is the globally accepted, highly professional way to track changes to a document over time?', '{"a":"Using the alphabet (File A, File B, File C).","b":"Using sequential alphanumeric numbering (like v01, v02, v03).","c":"Highlighting the text in different colors.","d":"Putting your initials at the end of the file name every time."}'::jsonb, 'b', 'Audit Trail Protocol', 'Lesson 3', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759729b', '69a6d7f3258e2632ad6e3719', 161, 'If you use the "Cut" command on a family photo, what are you telling the computer to do?', '{"a":"Make the photo physically smaller on the screen.","b":"Create a backup copy of the photo.","c":"Move the photo entirely to a new location, leaving absolutely nothing behind in the old spot.","d":"Change the colors of the photo to black and white."}'::jsonb, 'c', 'Pure Movement', 'Lesson 4', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a0', '69a6d7f3258e2632ad6e3719', 166, 'What happens if you highlight a file and press Shift + Delete?', '{"a":"The file is copied twice.","b":"The file is moved to the Recycle Bin.","c":"The file bypasses the Recycle Bin entirely and is permanently, immediately incinerated.","d":"The file name is changed to capital letters."}'::jsonb, 'c', 'Incineration Trick', 'Lesson 4', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a1', '69a6d7f3258e2632ad6e3719', 167, 'What is the exact architectural purpose of the Recycle Bin in Windows?', '{"a":"To empty itself automatically every 5 minutes.","b":"To act as a \"soft-delete\" safety net so you can rescue accidental mistakes before they are gone forever.","c":"To clean viruses off your computer.","d":"To organize your photos."}'::jsonb, 'b', 'Soft Delete Architecture', 'Lesson 4', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972ad', '69a6d7f3258e2632ad6e3719', 179, 'What does a "Solid Green Circle with a white checkmark" icon mean next to a OneDrive file?', '{"a":"The file has a virus.","b":"The file is online-only and cannot be opened without Wi-Fi.","c":"The file is fully downloaded to your physical computer and is completely safe to open even if you have zero internet connection.","d":"The file is currently being deleted."}'::jsonb, 'c', 'Fully Downloaded Icon', 'Lesson 6', '2026-03-22T12:17:57.186Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b0', '69a6d7f3258e2632ad6e3719', 182, 'If you want to send a massive 5-Gigabyte video to a colleague, what is the safest and most modern way to do it?', '{"a":"Send it as a standard email attachment.","b":"Generate a secure Cloud link and email them the link instead of the file.","c":"Print it out.","d":"Put it on a floppy disk."}'::jsonb, 'b', 'Modern Payload Delivery', 'Lesson 6', '2026-03-22T12:17:57.187Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b1', '69a6d7f3258e2632ad6e3719', 183, 'How is the Windows operating system able to find a lost file almost instantly when you use the Search Bar?', '{"a":"It physically scans the entire hard drive from start to finish every time you press Enter.","b":"It constantly reads and updates a secret, highly optimized Master Index database in the background.","c":"It guesses based on your typing history.","d":"It asks the internet to find it."}'::jsonb, 'b', 'System Optimization', 'Lesson 7', '2026-03-22T12:17:57.187Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972bf', '69a6d7f3258e2632ad6e3719', 197, 'When is a physical USB drive still absolutely necessary in the modern, cloud-based world?', '{"a":"When you have a very fast, stable fiber internet connection.","b":"When you want to send a short text message.","c":"During severe load shedding, when traveling in remote areas, or for highly secure \"air-gapped\" situations.","d":"When you want to organize your desktop."}'::jsonb, 'c', 'Physical Media Mandate', 'Lesson 9', '2026-03-22T12:17:57.189Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c0', '69a6d7f3258e2632ad6e3719', 198, 'What does HDD stand for in computer hardware?', '{"a":"High Data Device","b":"Hard Disk Drive","c":"Heavy Digital Drive","d":"Hidden Data Directory"}'::jsonb, 'b', 'Acronym Definition', 'Lesson 9', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c4', '69a6d7f3258e2632ad6e3719', 202, 'What does the "Safely Remove Hardware" protocol actually tell the operating system to do?', '{"a":"Forcefully flush all pending cached data and safely cut the logical software power to the external drive.","b":"Format the drive and erase all files.","c":"Copy the files to the Cloud.","d":"Print a receipt of the transfer."}'::jsonb, 'a', 'Power Cutting Safety', 'Lesson 9', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c8', '69a6d7f3258e2632ad6e3719', 206, 'What is a "Dummy File" used for during a practical training lab?', '{"a":"To trick the computer into running faster.","b":"A safe, empty, or unimportant file used to practice organizing and testing folder structures without risking real data.","c":"To hide viruses from the system.","d":"To permanently fill up the hard drive."}'::jsonb, 'b', 'Training Data', 'Lesson 10', '2026-03-22T12:17:57.191Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c9', '69a6d7f3258e2632ad6e3719', 207, 'According to Lesson 10, why must students physically build the project structure themselves instead of just reading about it?', '{"a":"To pass the time in class.","b":"Because physically performing the tasks is the only way to transform theoretical head-knowledge into permanent muscle memory.","c":"Because the computer requires a password to read theory.","d":"To use up internet data."}'::jsonb, 'b', 'Theory to Practice', 'Lesson 10', '2026-03-22T12:17:57.191Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275971fb', '69a6d7f3258e2632ad6e3719', 1, 'What acts as the manager to turn on the physical machinery of the computer?', '{"a":"The Cloud","b":"The Operating System","c":"A Flash Drive","d":"A ZIP folder"}'::jsonb, 'b', 'The Operating System', 'Lesson 1', '2026-03-22T12:17:57.139Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275971fc', '69a6d7f3258e2632ad6e3719', 2, 'What is the digital equivalent of a physical drawer where you keep your work organized?', '{"a":"A file","b":"A folder","c":"The keyboard","d":"The internet"}'::jsonb, 'b', 'Digital Folders', 'Lesson 1', '2026-03-22T12:17:57.141Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597201', '69a6d7f3258e2632ad6e3719', 7, 'Every time you save a receipt, take a screenshot, or type a letter, what are you creating?', '{"a":"A new piece of hardware","b":"A new piece of digital data (a file)","c":"A new operating system","d":"A new internet connection"}'::jsonb, 'b', 'Digital Data', 'Lesson 1', '2026-03-22T12:17:57.145Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597204', '69a6d7f3258e2632ad6e3719', 10, 'How can you select a massive block of 20 files all at once without clicking them one by one?', '{"a":"Click the first file, hold the Shift key, and click the last file.","b":"Double-click the first file.","c":"Drag the files to the desktop.","d":"Press the spacebar 20 times."}'::jsonb, 'a', 'Selecting Multiple Files', 'Lesson 2', '2026-03-22T12:17:57.147Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597206', '69a6d7f3258e2632ad6e3719', 12, 'If you want to see highly analytical details like the exact Date Modified and Size of your files, which view should you use?', '{"a":"Extra Large Icons","b":"Details View","c":"Small Icons","d":"Hidden View"}'::jsonb, 'b', 'Details View', 'Lesson 2', '2026-03-22T12:17:57.148Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759720b', '69a6d7f3258e2632ad6e3719', 17, 'Why is the YYYY-MM-DD date format so important for naming files?', '{"a":"It ensures computer systems can sort the files mathematically and chronologically without error.","b":"It is the only format that the internet can read.","c":"It prevents hackers from stealing your data.","d":"It forces the computer to make a backup copy."}'::jsonb, 'a', 'Sorting Efficiency', 'Lesson 3', '2026-03-22T12:17:57.151Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597218', '69a6d7f3258e2632ad6e3719', 30, 'Why was the file extension originally invented in the early days of computing?', '{"a":"To make file names look more professional.","b":"To let the operating system quickly identify the file type without wasting processing power to scan it.","c":"To stop people from sharing files.","d":"To track how long a person spent working on a document."}'::jsonb, 'b', 'Extension Origin', 'Lesson 5', '2026-03-22T12:17:57.156Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759721a', '69a6d7f3258e2632ad6e3719', 32, 'Government security organizations warn that unsolicited .exe files are the primary delivery mechanism for what?', '{"a":"Software updates","b":"Cloud backups","c":"Malware, spyware, and ransomware attacks","d":"Free internet access"}'::jsonb, 'c', 'Security Warnings', 'Lesson 5', '2026-03-22T12:17:57.157Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759721b', '69a6d7f3258e2632ad6e3719', 33, 'If you want to open a file with a program other than the computer''s default choice, what menu should you use?', '{"a":"The \"Send To\" menu","b":"The \"Open With\" menu","c":"The \"Rename\" menu","d":"The \"Delete\" menu"}'::jsonb, 'b', 'Open With Menu', 'Lesson 5', '2026-03-22T12:17:57.158Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597220', '69a6d7f3258e2632ad6e3719', 38, 'Microsoft OneDrive uses advanced 256-bit AES encryption. What does this do?', '{"a":"It scrambles and locks your data mathematically, ensuring hackers cannot read your private documents.","b":"It translates your documents into a different language.","c":"It makes the files small enough to fit in an email.","d":"It permanently deletes old files to save space."}'::jsonb, 'a', 'Encryption', 'Lesson 6', '2026-03-22T12:17:57.159Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597222', '69a6d7f3258e2632ad6e3719', 40, 'What is universally mandated by IT professionals as the best defense against catastrophic data loss (like theft or fire)?', '{"a":"Printing everything out.","b":"Using automated, off-site Cloud synchronization.","c":"Memorizing all your passwords.","d":"Buying a new laptop every year."}'::jsonb, 'b', 'Disaster Recovery', 'Lesson 6', '2026-03-22T12:17:57.160Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597232', '69a6d7f3258e2632ad6e3719', 56, 'Will placing your legal documents or family photos into a ZIP file lower their quality?', '{"a":"Yes, ZIP files always destroy high-quality photos.","b":"No, the algorithm is mathematically lossless, meaning quality is perfectly preserved.","c":"Only if the ZIP file is sent over Wi-Fi.","d":"Yes, text will be missing when they are unpacked."}'::jsonb, 'b', 'Data Integrity', 'Lesson 8', '2026-03-22T12:17:57.163Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597239', '69a6d7f3258e2632ad6e3719', 63, 'Why is it dangerous to rely solely on a USB drive as your only backup?', '{"a":"Because they are easily lost, stolen, or mechanically broken.","b":"Because they cost thousands of dollars.","c":"Because they automatically delete files after 30 days.","d":"Because they cannot hold pictures."}'::jsonb, 'a', 'Backup Risks', 'Lesson 9', '2026-03-22T12:17:57.165Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759723a', '69a6d7f3258e2632ad6e3719', 64, 'What happens when you physically build a project structure yourself during a practical lab?', '{"a":"Your computer might crash.","b":"You turn head-knowledge into permanent muscle memory.","c":"You bypass the need to take an assessment.","d":"You automatically upgrade your operating system."}'::jsonb, 'b', 'Practical Memory', 'Lesson 10', '2026-03-22T12:17:57.165Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759723b', '69a6d7f3258e2632ad6e3719', 65, 'According to senior IT professionals, why should you avoid nesting folders deeper than 4 or 5 levels?', '{"a":"Because you will run out of hard drive space.","b":"Because deeply buried files become too long for the system''s 260-character limit, causing catastrophic errors when opening or moving them.","c":"Because the internet cannot see folders that deep.","d":"Because it looks messy on the screen."}'::jsonb, 'b', 'Deep Nesting Risks', 'Lesson 10', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759723e', '69a6d7f3258e2632ad6e3719', 68, 'If a system path exceeds the MAX_PATH limit of 260 characters, what could fail?', '{"a":"The mouse might stop working.","b":"The screen might turn off.","c":"The ability to open, move, or safely backup that file to the cloud.","d":"The keyboard will lock up."}'::jsonb, 'c', 'MAX_PATH Limit', 'Lesson 10', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759723f', '69a6d7f3258e2632ad6e3719', 69, 'What is a "dummy file" used for in a practical lab?', '{"a":"To test a folder structure safely without risking real, important data.","b":"To permanently delete viruses.","c":"To trick the teacher.","d":"To fill up the hard drive so no one else can use it."}'::jsonb, 'a', 'Dummy Files', 'Lesson 10', '2026-03-22T12:17:57.166Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597246', '69a6d7f3258e2632ad6e3719', 76, 'Why is it a bad idea to rely purely on your memory to find unorganised files?', '{"a":"Because human memory is perfect.","b":"Because it forces you to use the \"Search Trap,\" wasting valuable time trying to remember exact file names.","c":"Because the computer will not let you use the search bar.","d":"Because files change their names automatically."}'::jsonb, 'b', 'The Search Trap', 'Lesson 1', '2026-03-22T12:17:57.167Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759724f', '69a6d7f3258e2632ad6e3719', 85, 'Why should you avoid naming a folder something generic like "Stuff" or "Miscellaneous"?', '{"a":"The computer cannot read the word \"Stuff.\"","b":"It will create massive frustration later because you will not know what is inside without opening it.","c":"The internet will delete the folder.","d":"It takes up too much physical memory."}'::jsonb, 'b', 'Generic Names', 'Lesson 3', '2026-03-22T12:17:57.168Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597251', '69a6d7f3258e2632ad6e3719', 87, 'What is "Digital Grammar"?', '{"a":"Using proper spelling in a Word document.","b":"Understanding the strict rules of how the computer''s core code reads and routes file names.","c":"Learning how to type faster.","d":"Using capital letters for everything."}'::jsonb, 'b', 'Digital Grammar', 'Lesson 3', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597253', '69a6d7f3258e2632ad6e3719', 89, 'What is a "Version Control" audit trail?', '{"a":"A list of all the websites you visited.","b":"A professional system of using sequential numbers (v01, v02, v03) so a corporate team can clearly track changes to a document over time.","c":"A way to lock your computer.","d":"A program that checks your spelling."}'::jsonb, 'b', 'Sequential Numbering', 'Lesson 3', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597254', '69a6d7f3258e2632ad6e3719', 90, 'How do you open the hidden, classic rename menu in Windows 11 if you prefer the old way?', '{"a":"You click \"Show more options\" at the bottom of the right-click menu.","b":"You unplug the keyboard.","c":"You search for it on the internet.","d":"You turn the computer off and on again."}'::jsonb, 'a', 'Show More Options', 'Lesson 3', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597257', '69a6d7f3258e2632ad6e3719', 93, 'If your desktop is a mess and you want to clean it up by moving a file into a specific folder so it no longer sits on the desktop, which command should you use?', '{"a":"Cut","b":"Copy","c":"Undo","d":"Print"}'::jsonb, 'a', 'Re-pathing Data', 'Lesson 4', '2026-03-22T12:17:57.169Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759725a', '69a6d7f3258e2632ad6e3719', 96, 'What does the Common User Access (CUA) standard refer to?', '{"a":"The rules for sending an email.","b":"The globally standardized keyboard shortcuts (like Ctrl+C and Ctrl+V) used by all modern offices.","c":"The password to access the internet.","d":"The limit on how many folders you can make."}'::jsonb, 'b', 'Universal Shortcuts', 'Lesson 4', '2026-03-22T12:17:57.170Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759725e', '69a6d7f3258e2632ad6e3719', 100, 'Which file extension represents a standard Microsoft Word document?', '{"a":".mp3","b":".jpg","c":".docx","d":".exe"}'::jsonb, 'c', 'Word Extension', 'Lesson 5', '2026-03-22T12:17:57.171Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759726b', '69a6d7f3258e2632ad6e3719', 113, 'What is the low-level background process that constantly reads your files to make searching instantaneous?', '{"a":"The Command Bar","b":"The Recycle Bin","c":"The Search Indexer","d":"The Cloud Synchronizer"}'::jsonb, 'c', 'Search Indexing', 'Lesson 7', '2026-03-22T12:17:57.174Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597272', '69a6d7f3258e2632ad6e3719', 120, 'What is a common scenario where you would absolutely need to use a ZIP file?', '{"a":"When you want to watch a video.","b":"When you are applying for a job and need to group 7 different application documents into one single, neat attachment.","c":"When you want to print a document.","d":"When you are writing a short email to a friend."}'::jsonb, 'b', 'Grouping Documents', 'Lesson 8', '2026-03-22T12:17:57.176Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759727a', '69a6d7f3258e2632ad6e3719', 128, 'What does "USB" stand for?', '{"a":"Universal Serial Bus","b":"Unified System Block","c":"Universal Storage Box","d":"United System Backup"}'::jsonb, 'a', 'USB Standard', 'Lesson 9', '2026-03-22T12:17:57.178Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759727b', '69a6d7f3258e2632ad6e3719', 129, 'What is the main physical difference between an old HDD (Hard Disk Drive) and a modern SSD (Solid State Drive)?', '{"a":"An HDD uses the cloud; an SSD does not.","b":"An HDD has physical spinning metal disks and moving robot arms; an SSD has no moving parts at all and uses flash memory.","c":"An HDD is only for pictures; an SSD for documents.","d":"An HDD is much smaller than an SSD."}'::jsonb, 'b', 'SSD vs HDD Architecture', 'Lesson 9', '2026-03-22T12:17:57.178Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759727d', '69a6d7f3258e2632ad6e3719', 131, 'What does the system feature "Write Caching" do?', '{"a":"It writes data to the fast internal memory first, telling you the transfer is complete before the data has actually finished moving to the USB drive.","b":"It writes down your passwords safely.","c":"It cleans your computer screen.","d":"It stops you from copying files."}'::jsonb, 'a', 'RAM Priority', 'Lesson 9', '2026-03-22T12:17:57.179Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759727f', '69a6d7f3258e2632ad6e3719', 133, 'Which USB connector is the newer, smaller, oval-shaped one that can be plugged in upside down?', '{"a":"USB-A","b":"USB-B","c":"USB-C","d":"USB-D"}'::jsonb, 'c', 'USB-C Port', 'Lesson 9', '2026-03-22T12:17:57.179Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597281', '69a6d7f3258e2632ad6e3719', 135, 'Why is "broad and shallow" better than "narrow and deep" when making folders?', '{"a":"It looks better on the screen.","b":"It prevents the textual file path from exceeding the 260-character limit, which would cause catastrophic system errors.","c":"It avoids the hard path limit.","d":"It saves you money on internet data."}'::jsonb, 'b', 'System Errors Prevention', 'Lesson 10', '2026-03-22T12:17:57.180Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b027597290', '69a6d7f3258e2632ad6e3719', 150, 'How does the "Address Bar" act exactly like a GPS?', '{"a":"It tells you how long it will take to download a file.","b":"It shows you the exact path of folders you clicked to get to your current location (e.g., C: > Documents > Work).","c":"It gives you driving directions to the office.","d":"It tracks your mouse movements on the screen."}'::jsonb, 'b', 'GPS Routing', 'Lesson 2', '2026-03-22T12:17:57.182Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b02759729d', '69a6d7f3258e2632ad6e3719', 163, 'What invisible part of the computer''s internal memory temporarily holds your cut or copied files while they wait to be pasted?', '{"a":"The C: Drive","b":"The Cloud","c":"The RAM","d":"The Clipboard"}'::jsonb, 'd', 'Temporary Storage', 'Lesson 4', '2026-03-22T12:17:57.183Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a3', '69a6d7f3258e2632ad6e3719', 169, 'What is a "File Extension"?', '{"a":"An extra cord you plug into the computer.","b":"The tiny dot and letters at the end of a file name that tell the computer what type of data is inside.","c":"A folder inside another folder.","d":"The date a file was created."}'::jsonb, 'b', 'Identification Suffix', 'Lesson 5', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a4', '69a6d7f3258e2632ad6e3719', 170, 'Why did early software engineers invent file extensions?', '{"a":"To stop users from copying files.","b":"So the operating system could mathematically identify the file format instantly, without wasting heavy power to scan the code inside.","c":"To make file names look longer and more complicated.","d":"To connect computers to the internet."}'::jsonb, 'b', 'Rapid Identification', 'Lesson 5', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a5', '69a6d7f3258e2632ad6e3719', 171, 'Which of the following file extensions strictly tells the computer that the file is an audio recording (music or voice)?', '{"a":".mp3","b":".docx","c":".pdf","d":".exe"}'::jsonb, 'a', 'Audio Format Extension', 'Lesson 5', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a7', '69a6d7f3258e2632ad6e3719', 173, 'If you do not see the file extensions on your computer screen, what is the most likely reason?', '{"a":"Your computer is broken.","b":"Windows hides them by default to protect everyday users from accidentally deleting them and breaking the file''s routing.","c":"You do not have the internet connected.","d":"The files do not have extensions."}'::jsonb, 'b', 'System Suffix Hiding', 'Lesson 5', '2026-03-22T12:17:57.184Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972a8', '69a6d7f3258e2632ad6e3719', 174, 'How can you force a .pdf file to open in a different program if you do not like the computer''s default choice?', '{"a":"Right-click the file and select \"Open With\" to choose your preferred software.","b":"Rename the file to a .docx.","c":"Delete the file and download it again.","d":"Unplug the computer."}'::jsonb, 'a', 'Application Overriding', 'Lesson 5', '2026-03-22T12:17:57.185Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972ac', '69a6d7f3258e2632ad6e3719', 178, 'What does "256-bit AES encryption" actually do to your files while they are in the Cloud?', '{"a":"It deletes them after 30 days.","b":"It mathematically scrambles and locks your data so hackers cannot read your private documents without your specific password.","c":"It changes the language of your documents.","d":"It shrinks the files to make them smaller."}'::jsonb, 'b', 'Data Scrambling', 'Lesson 6', '2026-03-22T12:17:57.186Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b2', '69a6d7f3258e2632ad6e3719', 184, 'What are Advanced Query Syntax (AQS) commands used for?', '{"a":"They are cheat codes (like \"type:\" or \"ext:\") that help you narrow down a search with mathematical precision.","b":"They are used to change your password.","c":"They format your hard drive.","d":"They create new folders."}'::jsonb, 'a', 'Filtering Precision', 'Lesson 7', '2026-03-22T12:17:57.187Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b4', '69a6d7f3258e2632ad6e3719', 186, 'What is the critical difference between "Date Created" and "Date Modified"?', '{"a":"There is no difference; they mean the exact same thing.","b":"Date Created is the birth date of the file; Date Modified is the exact time someone last made a change and pressed save.","c":"Date Created is only for folders; Date Modified is only for files.","d":"Date Modified changes automatically every single day."}'::jsonb, 'b', 'Birth vs Change', 'Lesson 7', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b5', '69a6d7f3258e2632ad6e3719', 187, 'Why is it significantly faster to search inside a specific, targeted folder rather than searching "This PC"?', '{"a":"Searching \"This PC\" forces the indexer to scan the entire massive system, taking significantly longer than a localized search.","b":"\"This PC\" only searches for pictures.","c":"Specific folders have better internet connections.","d":"\"This PC\" deletes files that it cannot find quickly."}'::jsonb, 'a', 'Scan Volume Efficiency', 'Lesson 7', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b6', '69a6d7f3258e2632ad6e3719', 188, 'How do special software components called "iFilters" help the Windows Search Bar?', '{"a":"They block spam emails.","b":"They mathematically break open complex documents (like PDFs) so the search indexer can read the actual words typed on the pages inside.","c":"They change the color of your screen.","d":"They organize your desktop icons."}'::jsonb, 'b', 'Interior Reading', 'Lesson 7', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b8', '69a6d7f3258e2632ad6e3719', 190, 'What is the hard, unforgiving size limit for sending an email attachment on a standard SMTP server?', '{"a":"1 Gigabyte (GB)","b":"500 Kilobytes (KB)","c":"25 Megabytes (MB)","d":"100 Megabytes (MB)"}'::jsonb, 'c', 'Payload Limits', 'Lesson 8', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972b9', '69a6d7f3258e2632ad6e3719', 191, 'What will the Simple Mail Transfer Protocol (SMTP) server do if you try to attach a 30 MB file to an email?', '{"a":"It will automatically compress it for you.","b":"It will actively block it and bounce it back to you with a Non-Delivery Report (NDR) error.","c":"It will send it, but it will take three days to arrive.","d":"It will delete your entire email account."}'::jsonb, 'b', 'System Rejection', 'Lesson 8', '2026-03-22T12:17:57.188Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972bb', '69a6d7f3258e2632ad6e3719', 193, 'How does the "DEFLATE" algorithm shrink a file without ruining the quality of the data?', '{"a":"It cuts the edges off your photos.","b":"It permanently lowers the resolution of your videos.","c":"It safely replaces large, repeating binary patterns with tiny mathematical dictionary shortcuts.","d":"It deletes random words from your documents."}'::jsonb, 'c', 'Repeating Patterns Replacement', 'Lesson 8', '2026-03-22T12:17:57.189Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972be', '69a6d7f3258e2632ad6e3719', 196, 'Do you need to buy expensive third-party software to create a ZIP file on a modern computer?', '{"a":"Yes, you must pay for a subscription.","b":"No, the mathematical ability to compress and extract files is built natively and entirely free into Windows 11.","c":"Only if the file is larger than 1GB.","d":"Yes, you have to download special tools from the internet."}'::jsonb, 'b', 'Free System Utilities', 'Lesson 8', '2026-03-22T12:17:57.189Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('69bfddf5d2c9d7b0275972c2', '69a6d7f3258e2632ad6e3719', 200, 'What is "Write Caching" on a Windows computer?', '{"a":"A feature that hides your passwords.","b":"An advanced trick where the computer writes data to fast internal memory first, falsely reporting that a USB transfer is \"complete\" while it actually finishes saving in the background.","c":"A way to clean your hard drive.","d":"A tool for writing emails faster."}'::jsonb, 'b', 'Falsified Success Reports', 'Lesson 9', '2026-03-22T12:17:57.190Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a5c', '69bfb458456d9fffaa203a47', 1, 'Which tab opens Backstage View in Microsoft Word?', '{"a":"Home","b":"Insert","c":"File","d":"Review"}'::jsonb, 'c', 'Word Interface (3.1)', 'Lesson 1', '2026-05-29T10:43:07.051Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a5d', '69bfb458456d9fffaa203a47', 2, 'Which part of the Word window shows the document name?', '{"a":"Status Bar","b":"Title Bar","c":"Ribbon","d":"Ruler"}'::jsonb, 'b', 'Word Interface (3.1)', 'Lesson 1', '2026-05-29T10:43:07.052Z') ON CONFLICT (_id) DO NOTHING;
