INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a60', '69bfb458456d9fffaa203a47', 5, 'Which feature is used to place frequently used commands for quick access?', '{"a":"Styles Pane","b":"Quick Access Toolbar","c":"Task Pane","d":"Review Pane"}'::jsonb, 'b', 'Word Interface (3.1)', 'Lesson 1', '2026-05-29T10:43:07.053Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a61', '69bfb458456d9fffaa203a47', 6, 'Which tab would you click first if you want to print a document?', '{"a":"Design","b":"Insert","c":"File","d":"Layout"}'::jsonb, 'c', 'Word Interface (3.1)', 'Lesson 1', '2026-05-29T10:43:07.053Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a62', '69bfb458456d9fffaa203a47', 7, 'Which command saves changes to the current document?', '{"a":"Save","b":"Save As","c":"Export","d":"Close"}'::jsonb, 'a', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.054Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a63', '69bfb458456d9fffaa203a47', 8, 'Which command is best when you want to save a document with a new name?', '{"a":"Open","b":"Save As","c":"Print","d":"New"}'::jsonb, 'b', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.054Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a64', '69bfb458456d9fffaa203a47', 9, 'Which file format is the normal Word document format?', '{"a":".pptx","b":".xlsx","c":".docx","d":".txt"}'::jsonb, 'c', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.054Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a65', '69bfb458456d9fffaa203a47', 10, 'Which file type is commonly used when you do not want others to edit the document easily?', '{"a":"PDF","b":"DOCX","c":"TXT","d":"RTF"}'::jsonb, 'a', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.055Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a66', '69bfb458456d9fffaa203a47', 11, 'Which command opens an existing document?', '{"a":"New","b":"Save","c":"Open","d":"Replace"}'::jsonb, 'c', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.055Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a67', '69bfb458456d9fffaa203a47', 12, 'Saving a file to OneDrive is an example of saving to:', '{"a":"A printer","b":"Cloud storage","c":"A toolbar","d":"A footer"}'::jsonb, 'b', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.055Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a68', '69bfb458456d9fffaa203a47', 13, 'Which is the best reason to use Save As?', '{"a":"To close Word","b":"To create another copy with a different name or location","c":"To zoom in","d":"To underline text"}'::jsonb, 'b', 'Create, Open, Save (3.2)', 'Lesson 2', '2026-05-29T10:43:07.055Z') ON CONFLICT (_id) DO NOTHING;
