INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a6c', '69bfb458456d9fffaa203a47', 17, 'What is the blinking vertical line in a document called?', '{"a":"Cursor or insertion point","b":"Margin","c":"Footer","d":"Border"}'::jsonb, 'a', 'Typing and Navigation (3.3)', 'Lesson 3', '2026-05-29T10:43:07.056Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a6d', '69bfb458456d9fffaa203a47', 18, 'Which bar helps you move up and down through a long document?', '{"a":"Formula bar","b":"Scroll bar","c":"Status bar","d":"Title bar"}'::jsonb, 'b', 'Typing and Navigation (3.3)', 'Lesson 3', '2026-05-29T10:43:07.056Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a6e', '69bfb458456d9fffaa203a47', 19, 'Which shortcut is commonly used to move to a specific page in Word through the Go To feature?', '{"a":"Ctrl + G","b":"Ctrl + B","c":"Ctrl + U","d":"Ctrl + P"}'::jsonb, 'a', 'Typing and Navigation (3.3)', 'Lesson 3', '2026-05-29T10:43:07.057Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a6f', '69bfb458456d9fffaa203a47', 20, 'Pressing the Tab key usually moves the cursor:', '{"a":"To the left margin","b":"To the next tab stop or cell","c":"To the top of the page","d":"To the title bar"}'::jsonb, 'b', 'Typing and Navigation (3.3)', 'Lesson 3', '2026-05-29T10:43:07.057Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a70', '69bfb458456d9fffaa203a47', 21, 'Before changing existing text formatting, what must you usually do first?', '{"a":"Save the document","b":"Select the text","c":"Print the page","d":"Close the file"}'::jsonb, 'b', 'Editing and Selecting Text (3.4)', 'Lesson 4', '2026-05-29T10:43:07.057Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a196dbb753d5ad1ec5a4a71', '69bfb458456d9fffaa203a47', 22, 'Which action usually selects a single word quickly?', '{"a":"Triple-click","b":"Double-click","c":"Right-click","d":"Press Esc"}'::jsonb, 'b', 'Editing and Selecting Text (3.4)', 'Lesson 4', '2026-05-29T10:43:07.057Z') ON CONFLICT (_id) DO NOTHING;
