INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a870b23189401ddc8a35aa7', '6a2d660e3c26ac04a78d8308', 20, 'Does filtering delete hidden rows?', '{"a":"Yes, unless the workbook is saved","b":"No, it only changes which rows are visible","c":"Only when filtering text","d":"Yes, hidden rows are permanently removed"}'::jsonb, 'b', 'Sort & Filter (5.6)', 'Lesson 6', '2026-08-20T14:11:47.355Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('6a870b23189401ddc8a35aaf', '6a2d660e3c26ac04a78d8308', 28, 'What does filtering do?', '{"a":"Temporarily shows only rows matching selected criteria","b":"Creates a copy of the workbook","c":"Permanently rearranges every row","d":"Deletes rows that do not match"}'::jsonb, 'a', 'Sort & Filter (5.6)', 'Lesson 6', '2026-08-20T14:11:47.358Z') ON CONFLICT (_id) DO NOTHING;
