INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('b2761fde42a97988ed658a0a', '6a8452f685e0de577163a431', 1, 'What is digital drawing?', '{"a":"Typing numbers into Excel","b":"Creating pictures or designs using a computer or digital device","c":"Printing documents from Microsoft Word","d":"Writing only with a pencil on paper"}'::jsonb, 'b', 'Why Digital Drawing Matters', 'Lesson 1', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
