INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('4b62ec957b60bbdd8efce33b', '6a8452f685e0de577163a431', 191, 'Why should you ask before printing in a classroom?', '{"a":"Printing uses paper and ink","b":"Printing improves every drawing automatically","c":"Printing replaces saving","d":"Printing deletes the picture"}'::jsonb, 'a', 'Safety, Respect, and Good Habits', 'Digital Citizenship & Safety', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('9fac005dd85b2f9539f144ed', '6a8452f685e0de577163a431', 192, 'What should you avoid in a community drawing?', '{"a":"Labels","b":"Roads","c":"Disrespectful or embarrassing representations","d":"Trees"}'::jsonb, 'c', 'Safety, Respect, and Good Habits', 'Digital Citizenship & Safety', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('97a838b6e4b8c70134ec8737', '6a8452f685e0de577163a431', 193, 'What should you do if the text is hard to read?', '{"a":"Print immediately","b":"Delete the whole computer","c":"Change size, colour, or placement","d":"Leave it hidden"}'::jsonb, 'c', 'Safety, Respect, and Good Habits', 'Digital Citizenship & Safety', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('b381d2f608e33ebd933d5664', '6a8452f685e0de577163a431', 194, 'What should you do if too many colours make the picture confusing?', '{"a":"Close without saving","b":"Simplify the colour choices","c":"Add more random colours","d":"Remove all tools"}'::jsonb, 'b', 'Safety, Respect, and Good Habits', 'Digital Citizenship & Safety', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('3f1cc1427b8db27aa81afb91', '6a8452f685e0de577163a431', 195, 'What should you do if you used too many stamps?', '{"a":"Print ten copies","b":"Add more stamps","c":"Delete another learner’s work","d":"Remove or undo some and keep the scene clear"}'::jsonb, 'd', 'Safety, Respect, and Good Habits', 'Digital Citizenship & Safety', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
