INSERT INTO assignment_questions (_id, module_id, question_number, question, options, correct_answer, section, lesson_reference, created_at) VALUES ('5db0696d65f68c7799c9031d', '6a8452f685e0de577163a431', 197, 'What is a good habit before closing a drawing program?', '{"a":"Remove the mouse","b":"Turn off the keyboard","c":"Save your work","d":"Delete your work"}'::jsonb, 'c', 'Safety, Respect, and Good Habits', 'Digital Citizenship & Safety', '2026-09-18T11:08:17.805Z') ON CONFLICT (_id) DO NOTHING;
